// ── FIX M-1: field-level validation errors ────────────────────────
//
// Before this fix, error.middleware.ts's `errors: Record<string, string[]>`
// object (built for every ZodError) was never read anywhere on the
// frontend — every validation failure surfaced as the same generic
// message regardless of which field(s) actually failed.

describe('parseApiError — fieldErrors (FIX M-1)', () => {
  it('extracts fieldErrors from a 400 with a body.* validation errors object', () => {
    const err = makeAxiosError(400, 'Validation failed', {}, {
      'body.title':       ['Title must be at least 3 characters'],
      'body.description': ['Description must be at least 10 characters'],
    }, undefined, undefined, {
      'body.title':       [{ code: 'too_small', params: { minimum: 3, type: 'string' } }],
      'body.description': [{ code: 'too_small', params: { minimum: 10, type: 'string' } }],
    });
    const result = parseApiError(err);
    expect(result.fieldErrors).toEqual({
      title:       ['العنوان يجب أن يتكون من 3 أحرف على الأقل'],
      description: ['الوصف يجب أن يتكون من 10 أحرف على الأقل'],
    });
  });

  it('strips the query.* wrapper prefix the same way as body.*', () => {
    const err = makeAxiosError(400, 'Validation failed', {}, {
      'query.sortBy': ["Invalid enum value. Expected 'createdAt' | 'price' | 'views'"],
    }, undefined, undefined, {
      'query.sortBy': [{ code: 'invalid_enum_value' }],
    });
    const result = parseApiError(err);
    expect(result.fieldErrors).toEqual({
      sortBy: ['قيمة هذا الحقل غير صالحة'],
    });
  });

  it('strips the params.* wrapper prefix the same way', () => {
    const err = makeAxiosError(400, 'Validation failed', {}, {
      'params.id': ['Ad ID is required'],
    }, undefined, undefined, {
      'params.id': [{ code: 'too_small', params: { minimum: 1, type: 'string' } }],
    });
    const result = parseApiError(err);
    expect(result.fieldErrors).toEqual({ id: ['المعرّف مطلوب'] });
  });

  it('leaves a bare "general" key untouched (matches error.middleware.ts fallback for an empty Zod path)', () => {
    const err = makeAxiosError(400, 'Validation failed', {}, {
      general: ['Something about the whole request was invalid'],
    }, undefined, undefined, {
      general: [{ code: 'custom' }],
    });
    const result = parseApiError(err);
    expect(result.fieldErrors).toEqual({
      general: ['البيانات المدخلة غير صالح'],
    });
  });

  it('preserves multiple messages for the same field, in order', () => {
    const err = makeAxiosError(400, 'Validation failed', {}, {
      'body.price': ['Price must be a positive number', 'Price cannot have more than 2 decimal places'],
    }, undefined, undefined, {
      'body.price': [
        { code: 'too_small', params: { minimum: 0, type: 'number', exclusive: true } },
        { code: 'not_multiple_of' },
      ],
    });
    const result = parseApiError(err);
    expect(result.fieldErrors?.price).toEqual([
      'السعر يجب أن يكون أكبر من 0',
      'السعر غير صالح (عدد المنازل العشرية غير مسموح)',
    ]);
  });

  it('sanitises (HTML-strips) individual field error messages the same way as the top-level message, falling back to the literal table when no errorMeta is present', () => {
    const err = makeAxiosError(400, 'Validation failed', {}, {
      'body.title': ['<script>alert(1)</script>Title is required'],
    });
    const result = parseApiError(err);
    expect(result.fieldErrors?.title?.[0]).not.toContain('<script>');
    expect(result.fieldErrors?.title?.[0]).toBe('البيانات المدخلة غير صحيحة');
  });

  it('is undefined (not an empty object) when the backend sends no errors field', () => {
    const err = makeAxiosError(400, 'Some other 400');
    expect(parseApiError(err).fieldErrors).toBeUndefined();
  });

  it('is never populated for non-400 statuses, even if the body happens to have an errors-shaped field', () => {
    // Defends against a coincidental `errors` key on a 403/404/500 body
    // being misread as field-level validation detail it isn't.
    const err = makeAxiosError(403, 'Forbidden', {}, { 'body.title': ['nope'] });
    expect(parseApiError(err).fieldErrors).toBeUndefined();
  });

  it('ignores non-array values under a key rather than throwing', () => {
    const err = makeAxiosError(400, 'Validation failed', {}, {
      // @ts-expect-error — deliberately malformed shape to test defensive parsing
      'body.title': 'not an array',
    });
    expect(() => parseApiError(err)).not.toThrow();
    expect(parseApiError(err).fieldErrors).toBeUndefined();
  });
});

describe('parseApiError idempotency (FIX AUTH-MSG-01)', () => {
  // Regression coverage for the "double-parse" bug: apiClient's response
  // interceptor (client.ts) already calls parseApiError before rejecting,
  // so every rejection reaching a mutation's onError/a form's error prop is
  // already a ParsedError. Feeding that ParsedError into parseApiError a
  // second time must return it unchanged — not fall through to the generic
  // "حدث خطأ غير متوقع" fallback, which is what happened before this fix
  // (a ParsedError is neither an AxiosError nor an `instanceof Error`).

  it('returns an already-parsed 401 unchanged instead of the generic fallback', () => {
    const firstPass = parseApiError(makeAxiosError(401, 'ignored', {}, undefined, 'INVALID_CREDENTIALS'));
    const secondPass = parseApiError(firstPass);
    expect(secondPass).toEqual(firstPass);
    expect(secondPass.message).not.toBe('حدث خطأ غير متوقع');
    expect(secondPass.message).toBe('البريد الإلكتروني أو كلمة المرور غير صحيحة');
  });

  it('preserves code and fieldErrors through a second parse (RegisterForm flow)', () => {
    const firstPass = parseApiError(
      makeAxiosError(400, 'Email already in use', {}, undefined, 'EMAIL_ALREADY_EXISTS'),
    );
    const secondPass = parseApiError(firstPass);
    expect(secondPass.code).toBe('EMAIL_ALREADY_EXISTS');
    expect(secondPass.message).toBe(firstPass.message);
  });

  it('preserves a 429 rate-limit message through a second parse', () => {
    const firstPass = parseApiError(makeAxiosError(429, 'ignored', { 'retry-after': '120' }));
    const secondPass = parseApiError(firstPass);
    expect(secondPass.message).toBe(firstPass.message);
    expect(secondPass.statusCode).toBe(429);
  });

  it('still parses a raw AxiosError normally (does not treat every object as pre-parsed)', () => {
    const err = makeAxiosError(500, 'db exploded');
    const parsed = parseApiError(err);
    expect(parsed.message).toBe('خطأ في الخادم، يرجى المحاولة لاحقاً');
    expect(parsed.statusCode).toBe(500);
  });

  it('still falls through to the generic message for a truly unknown value', () => {
    expect(parseApiError({ foo: 'bar' }).message).toBe('حدث خطأ غير متوقع');
    expect(parseApiError(null).message).toBe('حدث خطأ غير متوقع');
  });
});

describe('getFieldError', () => {
  it('returns the first (translated) message for a field that has errors', () => {
    const err = makeAxiosError(400, 'Validation failed', {}, {
      'body.city': ['City is required', 'City must be a known city'],
    });
    const parsed = parseApiError(err);
    // FIX I18N-01: field messages are translated to Arabic — with no
    // errorMeta present (this call omits it), unrecognised English
    // messages fall back to the generic Arabic validation string
    // rather than passing the raw backend text through.
    expect(getFieldError(parsed, 'city')).toBe('البيانات المدخلة غير صحيحة');
  });

  it('returns undefined for a field with no errors', () => {
    const err = makeAxiosError(400, 'Validation failed', {}, {
      'body.city': ['City is required'],
    });
    const parsed = parseApiError(err);
    expect(getFieldError(parsed, 'title')).toBeUndefined();
  });

  it('returns undefined when the parsed error itself is undefined (e.g. mutation has not errored yet)', () => {
    expect(getFieldError(undefined, 'title')).toBeUndefined();
  });

  it('returns undefined when there are no fieldErrors at all', () => {
    const parsed = parseApiError(makeAxiosError(500, 'boom'));
    expect(getFieldError(parsed, 'title')).toBeUndefined();
  });
});

/**
 * __tests__/unit/lib/offlineQueue.test.ts
 *
 * Phase 1 / P0: offlineQueue.ts previously had 0% coverage.
 * The real queue lives in IndexedDB (public/sw.js); this module only
 * counts pending rows and asks the SW to replay. Tests mock IDB + SW.
 *
 * IndexedDB request handlers (onsuccess/onerror/onupgradeneeded) are
 * assigned by production code *after* open() returns, so the mock must
 * fire those events on a later macrotask (setTimeout) — not microtask —
 * or the handlers are still null when the event runs.
 */
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { getQueuedRequestCount, requestQueueReplay } from '@/lib/offlineQueue';

interface FakeIDBRequest {
  result: unknown;
  error: unknown;
  onsuccess: ((ev?: unknown) => void) | null;
  onerror: ((ev?: unknown) => void) | null;
  onupgradeneeded: ((ev?: unknown) => void) | null;
}

function scheduleSuccess(req: FakeIDBRequest, beforeSuccess?: () => void) {
  setTimeout(() => {
    beforeSuccess?.();
    req.onsuccess?.(undefined);
  }, 0);
}

function scheduleError(req: FakeIDBRequest) {
  setTimeout(() => {
    req.onerror?.(undefined);
  }, 0);
}

describe('offlineQueue', () => {
  const originalIndexedDB = globalThis.indexedDB;
  const originalNavigator = globalThis.navigator;

  afterEach(() => {
    Object.defineProperty(globalThis, 'indexedDB', {
      value: originalIndexedDB,
      configurable: true,
      writable: true,
    });
    Object.defineProperty(globalThis, 'navigator', {
      value: originalNavigator,
      configurable: true,
      writable: true,
    });
  });

  describe('getQueuedRequestCount', () => {
    it('returns 0 when indexedDB is unavailable', async () => {
      Object.defineProperty(globalThis, 'indexedDB', {
        value: undefined,
        configurable: true,
        writable: true,
      });

      await expect(getQueuedRequestCount()).resolves.toBe(0);
    });

    it('returns the object-store count on success', async () => {
      const countReq: FakeIDBRequest = {
        result: 3,
        error: null,
        onsuccess: null,
        onerror: null,
        onupgradeneeded: null,
      };
      const store = {
        count: vi.fn(() => {
          scheduleSuccess(countReq);
          return countReq;
        }),
      };
      const tx = { objectStore: vi.fn(() => store) };
      const db = {
        objectStoreNames: { contains: () => true },
        transaction: vi.fn(() => tx),
      };
      const openReq: FakeIDBRequest = {
        result: db,
        error: null,
        onsuccess: null,
        onerror: null,
        onupgradeneeded: null,
      };
      Object.defineProperty(globalThis, 'indexedDB', {
        value: {
          open: vi.fn(() => {
            scheduleSuccess(openReq);
            return openReq;
          }),
        },
        configurable: true,
        writable: true,
      });

      await expect(getQueuedRequestCount()).resolves.toBe(3);
      expect(db.transaction).toHaveBeenCalledWith('requests', 'readonly');
      expect(store.count).toHaveBeenCalled();
    });

    it('creates the object store on upgradeneeded when missing', async () => {
      const createObjectStore = vi.fn();
      const countReq: FakeIDBRequest = {
        result: 0,
        error: null,
        onsuccess: null,
        onerror: null,
        onupgradeneeded: null,
      };
      const db = {
        objectStoreNames: { contains: () => false },
        createObjectStore,
        transaction: vi.fn(() => ({
          objectStore: () => ({
            count: () => {
              scheduleSuccess(countReq);
              return countReq;
            },
          }),
        })),
      };
      const openReq: FakeIDBRequest = {
        result: db,
        error: null,
        onsuccess: null,
        onerror: null,
        onupgradeneeded: null,
      };
      Object.defineProperty(globalThis, 'indexedDB', {
        value: {
          open: vi.fn(() => {
            scheduleSuccess(openReq, () => {
              openReq.onupgradeneeded?.(undefined);
            });
            return openReq;
          }),
        },
        configurable: true,
        writable: true,
      });

      await expect(getQueuedRequestCount()).resolves.toBe(0);
      expect(createObjectStore).toHaveBeenCalledWith('requests', {
        keyPath: 'id',
        autoIncrement: true,
      });
    });

    it('returns 0 when the open request fails', async () => {
      const openReq: FakeIDBRequest = {
        result: null,
        error: new Error('open failed'),
        onsuccess: null,
        onerror: null,
        onupgradeneeded: null,
      };
      Object.defineProperty(globalThis, 'indexedDB', {
        value: {
          open: vi.fn(() => {
            scheduleError(openReq);
            return openReq;
          }),
        },
        configurable: true,
        writable: true,
      });

      await expect(getQueuedRequestCount()).resolves.toBe(0);
    });

    it('returns 0 when the count request fails', async () => {
      const countReq: FakeIDBRequest = {
        result: 0,
        error: new Error('count failed'),
        onsuccess: null,
        onerror: null,
        onupgradeneeded: null,
      };
      const db = {
        objectStoreNames: { contains: () => true },
        transaction: vi.fn(() => ({
          objectStore: () => ({
            count: () => {
              scheduleError(countReq);
              return countReq;
            },
          }),
        })),
      };
      const openReq: FakeIDBRequest = {
        result: db,
        error: null,
        onsuccess: null,
        onerror: null,
        onupgradeneeded: null,
      };
      Object.defineProperty(globalThis, 'indexedDB', {
        value: {
          open: vi.fn(() => {
            scheduleSuccess(openReq);
            return openReq;
          }),
        },
        configurable: true,
        writable: true,
      });

      await expect(getQueuedRequestCount()).resolves.toBe(0);
    });
  });

  describe('requestQueueReplay', () => {
    it('no-ops when serviceWorker is not supported', async () => {
      Object.defineProperty(globalThis, 'navigator', {
        value: {},
        configurable: true,
        writable: true,
      });

      await expect(requestQueueReplay()).resolves.toBeUndefined();
    });

    it('posts REPLAY_QUEUE_NOW to the active service worker', async () => {
      const postMessage = vi.fn();
      Object.defineProperty(globalThis, 'navigator', {
        value: {
          serviceWorker: {
            ready: Promise.resolve({ active: { postMessage } }),
          },
        },
        configurable: true,
        writable: true,
      });

      await requestQueueReplay();

      expect(postMessage).toHaveBeenCalledWith({ type: 'REPLAY_QUEUE_NOW' });
    });

    it('tolerates a registration with no active worker', async () => {
      Object.defineProperty(globalThis, 'navigator', {
        value: {
          serviceWorker: {
            ready: Promise.resolve({ active: null }),
          },
        },
        configurable: true,
        writable: true,
      });

      await expect(requestQueueReplay()).resolves.toBeUndefined();
    });
  });
});

/**
 * __tests__/unit/lib/prefetch.test.ts
 *
 * Coverage for lib/prefetch.ts. The most important surface here is the
 * internal serverFetch() helper (API-INT-09): it must distinguish
 * network failure / non-OK HTTP status / JSON parse failure, log the
 * real cause server-side only, and throw a generic Arabic message in
 * every case — never leaking the internal API path or raw error
 * details into something that could surface in an RSC error boundary.
 *
 * FIX API-SHAPE-01: prefetchCategories/prefetchAdList/prefetchAdDetail
 * must each cache the UNWRAPPED value the matching client hook expects
 * (useCategories/useAds/useAd all resolve via `.then(r => r.data.data)`)
 * — not the raw ApiResponse envelope, and for the paginated ad list,
 * reassembled into { items, meta } from the backend's real shape
 * (items directly on `data`, pagination under top-level
 * `meta.pagination`). This file previously asserted the cache held the
 * full envelope for prefetchCategories/prefetchAdDetail as if that were
 * correct — that was itself the bug this fix corrects, encoded into
 * the test. See lib/apiPagination.ts for the full backend-shape story.
 *
 * prefetchCategories / prefetchAdList / prefetchAdDetail are thin
 * wrappers around qc.prefetchQuery — tested here by asserting the
 * QueryClient actually ends up with the expected cached data, which
 * exercises the real queryFn (serverFetch) end-to-end via a mocked
 * global fetch rather than mocking prefetchQuery itself.
 */
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { QueryClient } from '@tanstack/react-query';
import {
  prefetchCategories,
  prefetchAdList,
  prefetchAdDetail,
  dehydrateClient,
} from '@/lib/prefetch';
import { queryKeys } from '@/lib/queryKeys';

function jsonResponse(body: unknown, init?: { status?: number }) {
  return {
    ok: (init?.status ?? 200) < 400,
    status: init?.status ?? 200,
    json: async () => body,
  } as Response;
}

describe('prefetch helpers', () => {
  let qc: QueryClient;
  let consoleErrorSpy: ReturnType<typeof vi.spyOn>;

  beforeEach(() => {
    qc = new QueryClient();
    vi.restoreAllMocks();
    consoleErrorSpy = vi.spyOn(console, 'error').mockImplementation(() => {});
  });

  describe('prefetchCategories', () => {
    // FIX API-SHAPE-01: GET /categories is not paginated — the backend
    // puts the flat array directly on `data`. The cache must hold that
    // array itself (matching useCategories()'s `.then(r => r.data.data)`),
    // not the { success, message, data } envelope around it.
    it('populates the query cache with the unwrapped categories array on success', async () => {
      const categories = [{ id: 'c1', name: 'Electronics', slug: 'electronics' }];
      vi.stubGlobal('fetch', vi.fn().mockResolvedValue(
        jsonResponse({ success: true, message: 'ok', data: categories }),
      ));

      await prefetchCategories(qc);

      const cached = qc.getQueryData(queryKeys.categories.all());
      expect(cached).toEqual(categories);
      vi.unstubAllGlobals();
    });

    it('caches an empty array when the backend returns no data field', async () => {
      vi.stubGlobal('fetch', vi.fn().mockResolvedValue(
        jsonResponse({ success: true, message: 'ok' }),
      ));

      await prefetchCategories(qc);

      expect(qc.getQueryData(queryKeys.categories.all())).toEqual([]);
      vi.unstubAllGlobals();
    });

    it('throws a generic Arabic message (not the raw network error) on connection failure', async () => {
      vi.stubGlobal('fetch', vi.fn().mockRejectedValue(new Error('ECONNREFUSED 10.0.0.1:4000')));

      // prefetchQuery itself swallows the queryFn error into query state
      // rather than rejecting, so assert on the thrown error indirectly
      // via the query's error state.
      await prefetchCategories(qc);
      const state = qc.getQueryState(queryKeys.categories.all());

      expect(state?.status).toBe('error');
      expect((state?.error as Error).message).toBe('فشل الاتصال بالخادم');
      expect((state?.error as Error).message).not.toMatch(/ECONNREFUSED/);
      vi.unstubAllGlobals();
    });

    it('throws a generic Arabic message including the status code on a non-OK HTTP response', async () => {
      vi.stubGlobal('fetch', vi.fn().mockResolvedValue(jsonResponse({}, { status: 503 })));

      await prefetchCategories(qc);
      const state = qc.getQueryState(queryKeys.categories.all());

      expect(state?.status).toBe('error');
      expect((state?.error as Error).message).toBe('طلب الخادم فشل (503)');
      vi.unstubAllGlobals();
    });

    it('throws a generic Arabic message when the response body is not valid JSON', async () => {
      vi.stubGlobal('fetch', vi.fn().mockResolvedValue({
        ok: true,
        status: 200,
        json: async () => { throw new SyntaxError('Unexpected token'); },
      } as Response));

      await prefetchCategories(qc);
      const state = qc.getQueryState(queryKeys.categories.all());

      expect(state?.status).toBe('error');
      expect((state?.error as Error).message).toBe('استجابة الخادم غير صالحة');
      vi.unstubAllGlobals();
    });
  });

  describe('prefetchAdList', () => {
    it('builds the query string from the given params and caches the result', async () => {
      const fetchSpy = vi.fn().mockResolvedValue(
        jsonResponse({ success: true, message: 'ok', data: [] }),
      );
      vi.stubGlobal('fetch', fetchSpy);

      await prefetchAdList(qc, { city: 'الرياض', page: 2, categoryId: undefined });

      const calledUrl = fetchSpy.mock.calls[0][0] as string;
      expect(calledUrl).toContain('/ads?');
      expect(calledUrl).toContain('city=');
      expect(calledUrl).toContain('page=2');
      // undefined params must be filtered out of the query string.
      expect(calledUrl).not.toContain('categoryId');

      vi.unstubAllGlobals();
    });

    it('omits the query string entirely when no params are given', async () => {
      const fetchSpy = vi.fn().mockResolvedValue(
        jsonResponse({ success: true, message: 'ok', data: [] }),
      );
      vi.stubGlobal('fetch', fetchSpy);

      await prefetchAdList(qc);

      const calledUrl = fetchSpy.mock.calls[0][0] as string;
      expect(calledUrl.endsWith('/ads')).toBe(true);

      vi.unstubAllGlobals();
    });

    // FIX API-SHAPE-01: the backend puts the ad array directly on `data`
    // and pagination info under the top-level `meta.pagination` — NOT
    // `data.items`/`data.meta`. The cache must hold the reassembled
    // { items, meta } shape useAds() expects.
    it('reassembles the backend\'s real shape (data: T[], meta.pagination) into { items, meta }', async () => {
      const ads = [{ id: 'ad-1', title: 'Test Ad' }];
      const pagination = { total: 1, page: 1, limit: 20, totalPages: 1, hasNextPage: false, hasPrevPage: false };
      vi.stubGlobal('fetch', vi.fn().mockResolvedValue(
        jsonResponse({ success: true, message: 'ok', data: ads, meta: { pagination } }),
      ));

      await prefetchAdList(qc, { page: 1 });

      const cached = qc.getQueryData(queryKeys.ads.list({ page: 1 }));
      expect(cached).toEqual({ items: ads, meta: pagination });
      vi.unstubAllGlobals();
    });

    it('caches an empty items array and empty meta when the backend response has neither', async () => {
      vi.stubGlobal('fetch', vi.fn().mockResolvedValue(
        jsonResponse({ success: true, message: 'ok' }),
      ));

      await prefetchAdList(qc, { page: 1 });

      const cached = qc.getQueryData(queryKeys.ads.list({ page: 1 }));
      expect(cached).toEqual({ items: [], meta: {} });
      vi.unstubAllGlobals();
    });
  });

  describe('prefetchAdDetail', () => {
    // FIX API-SHAPE-01: GET /ads/:id is not paginated — `data` is the
    // Ad object directly. The cache must hold that object itself
    // (matching useAd()'s `.then(r => r.data.data)`), not the
    // { success, message, data } envelope around it.
    it('caches the unwrapped ad object under the correct query key', async () => {
      const ad = { id: 'ad-1', title: 'Test Ad' };
      vi.stubGlobal('fetch', vi.fn().mockResolvedValue(
        jsonResponse({ success: true, message: 'ok', data: ad }),
      ));

      await prefetchAdDetail(qc, 'ad-1');

      const cached = qc.getQueryData(queryKeys.ads.detail('ad-1'));
      expect(cached).toEqual(ad);
      vi.unstubAllGlobals();
    });

    // FIX PERF-11: generateMetadata and the page component in
    // ads/[id]/page.tsx each call prefetchAdDetail with the same id
    // during the same render pass. React.cache() around the
    // underlying fetch means the second call must not hit the network
    // again. This uses a fresh, unique id per test (rather than the
    // shared 'ad-1' used above) since React.cache()'s memoization can
    // outlive a single test in this non-RSC test runtime.
    it('does not issue a second network request when called twice with the same id in the same pass', async () => {
      const id = `ad-cache-check-${Date.now()}`;
      const ad = { id, title: 'Test Ad' };
      const fetchSpy = vi.fn().mockResolvedValue(
        jsonResponse({ success: true, message: 'ok', data: ad }),
      );
      vi.stubGlobal('fetch', fetchSpy);

      const qcForMetadata = new QueryClient();
      const qcForPage      = new QueryClient();
      await prefetchAdDetail(qcForMetadata, id);
      await prefetchAdDetail(qcForPage, id);

      expect(fetchSpy).toHaveBeenCalledTimes(1);
      // Both QueryClients still end up with the (shared-promise) result,
      // unwrapped the same way a single call would produce.
      expect(qcForMetadata.getQueryData(queryKeys.ads.detail(id))).toEqual(ad);
      expect(qcForPage.getQueryData(queryKeys.ads.detail(id))).toEqual(ad);
      vi.unstubAllGlobals();
    });
  });

  describe('dehydrateClient', () => {
    it('returns a dehydrated state containing the cached queries', async () => {
      vi.stubGlobal('fetch', vi.fn().mockResolvedValue(
        jsonResponse({ success: true, message: 'ok', data: [] }),
      ));
      await prefetchCategories(qc);

      const dehydrated = dehydrateClient(qc);
      expect(dehydrated.queries.length).toBeGreaterThan(0);
      vi.unstubAllGlobals();
    });
  });
});

/**
 * __tests__/unit/middleware/middleware.test.ts
 *
 * Coverage targets:
 *  - isProtected: all PROTECTED_PREFIXES + edit regex
 *  - isAdminRoute: /admin paths
 *  - isAuthPage: /login, /register, /forgot-password, /reset-password
 *  - decodeToken: valid JWT / malformed / expired
 *  - isTokenExpired: expired / valid / 10s buffer
 *  - middleware function:
 *    1. Auth page + logged-in → redirect /dashboard
 *    2. Protected route + no token → redirect /login?from=path
 *    3. Protected route + valid token → passes through
 *    4. Admin route + no token → redirect /login
 *    5. Admin route + USER role → redirect /dashboard
 *    6. Admin route + ADMIN role → passes through
 *    7. Public route → passes through (no redirect)
 *    8. Role cookie validation (SEC-05): unknown role treated as null
 *    9. Request-ID header is always set on pass-through
 */
import { describe, it, expect, vi } from 'vitest';
import { NextRequest } from 'next/server';

// We test the middleware function directly — import it from the source.
// Because next/server is available in jsdom via vitest, this should work.
import { middleware } from '@/middleware';

// ── Helpers ───────────────────────────────────────────────────────

/**
 * Build a minimal JWT with the given payload (HS256 header, no real signature).
 * Sufficient for the middleware's pure-decode usage (it does NOT verify signatures).
 */
function makeJwt(payload: object): string {
  const header  = btoa(JSON.stringify({ alg: 'HS256', typ: 'JWT' })).replace(/=/g, '');
  const body    = btoa(JSON.stringify(payload)).replace(/=/g, '');
  return `${header}.${body}.fakesig`;
}

function futureExp(secondsFromNow = 900): number {
  return Math.floor(Date.now() / 1000) + secondsFromNow;
}

function pastExp(secondsAgo = 60): number {
  return Math.floor(Date.now() / 1000) - secondsAgo;
}

function makeRequest(
  pathname: string,
  opts: {
    token?: string | null;
    role?:  string | null;
  } = {},
): NextRequest {
  const url = new URL(`http://localhost${pathname}`);
  const req = new NextRequest(url);

  if (opts.token) {
    req.cookies.set('app_access_token', opts.token);
  }
  if (opts.role) {
    req.cookies.set('app_user_role', opts.role);
  }
  return req;
}

const VALID_TOKEN = makeJwt({ userId: 'user-1', exp: futureExp() });
const EXPIRED_TOKEN = makeJwt({ userId: 'user-1', exp: pastExp() });
const ADMIN_TOKEN = makeJwt({ userId: 'admin-1', exp: futureExp() });

// ── Public routes — no redirect ───────────────────────────────────

describe('middleware — public routes', () => {
  it('passes through / (homepage)', () => {
    const req = makeRequest('/');
    const res = middleware(req);
    expect(res.status).toBe(200);
    expect(res.headers.get('Location')).toBeNull();
  });

  it('passes through /ads/:id (ad detail)', () => {
    const req = makeRequest('/ads/clr123abc');
    const res = middleware(req);
    expect(res.status).toBe(200);
  });

  it('passes through /search', () => {
    const req = makeRequest('/search?q=laptops');
    const res = middleware(req);
    expect(res.status).toBe(200);
  });

  it('passes through /categories/:slug', () => {
    const req = makeRequest('/categories/electronics');
    const res = middleware(req);
    expect(res.status).toBe(200);
  });

  it('passes through /profile/:id', () => {
    const req = makeRequest('/profile/user-123');
    const res = middleware(req);
    expect(res.status).toBe(200);
  });
});

