import { useMemo, useState } from 'react';
import Link from 'next/link';
import { SafeImage } from '@/components/shared/ui/SafeImage';
import { AlertTriangle, MessageSquare, Loader2, Search, X } from 'lucide-react';
import { EmptyState } from '@/components/shared/feedback/EmptyState';
import { Button } from '@/components/shared/ui/Button';
import { useMyConversations } from '@/hooks/queries/useConversations';
import { usePresence } from '@/hooks/queries/usePresence';
import { useAuthStore, selectUser } from '@/store/auth.store';
import { ROUTES } from '@/lib/constants';
import { formatRelativeTime } from '@/lib/formatters';
import { getAvatarUrl } from '@/lib/cloudinary';
import { cn } from '@/lib/utils';
import type { Conversation, ConversationListItem } from '@/types/conversation.types';

/** Whichever side the caller ISN'T — the person this thread is with. */
function otherParty(conversation: Conversation, userId: string | undefined) {
  return conversation.buyerId === userId ? conversation.seller : conversation.buyer;
}

function contextLabel(conversation: ConversationListItem): string | null {
  if (conversation.ad?.title) return conversation.ad.title;
  if (conversation.serviceRequest?.listing?.title) return conversation.serviceRequest.listing.title;
  return null;
}

function previewText(conversation: ConversationListItem, userId: string | undefined): string {
  const last = conversation.lastMessage;
  if (!last) {
    return contextLabel(conversation) ?? 'محادثة عامة';
  }
  if (last.deletedAt) return 'تم حذف هذه الرسالة';
  const mine = userId && last.senderId === userId;
  const body = last.body.trim() || '…';
  return mine ? `أنت: ${body}` : body;
}

const PAGE_SIZE = 20;

interface Props {
  selectedId?: string;
}

export function ConversationList({ selectedId }: Props = {}) {
  const user = useAuthStore(selectUser);
  const [limit, setLimit] = useState(PAGE_SIZE);
  const [query, setQuery] = useState('');
  const { data, isLoading, isError, refetch, isFetching } = useMyConversations({ page: 1, limit });

  const items = data?.items ?? [];
  const hasMore = Boolean(data?.meta?.hasNextPage);
  const loadingMore = isFetching && !isLoading;

  const otherPartyIds = items.slice(0, 50).map((c) => otherParty(c, user?.id).id);
  const { data: onlineMap } = usePresence(otherPartyIds);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return items;
    return items.filter((c) => {
      const party = otherParty(c, user?.id);
      const ctx = contextLabel(c) ?? '';
      const preview = c.lastMessage?.body ?? '';
      return (
        party.name.toLowerCase().includes(q) ||
        ctx.toLowerCase().includes(q) ||
        preview.toLowerCase().includes(q)
      );
    });
  }, [items, query, user?.id]);

  const totalUnread = useMemo(
    () => items.reduce((sum, c) => sum + (c.unreadCount > 0 ? 1 : 0), 0),
    [items],
  );

  if (isLoading) {
    return (
      <div className="flex flex-col gap-0 divide-y" role="status" aria-label="جارٍ التحميل">
        {Array.from({ length: 6 }).map((_, i) => (
          <div key={i} className="flex items-center gap-3 p-4 animate-pulse">
            <div className="h-14 w-14 shrink-0 rounded-full bg-muted" />
            <div className="min-w-0 flex-1 space-y-2">
              <div className="h-3.5 w-1/3 rounded bg-muted" />
              <div className="h-3 w-2/3 rounded bg-muted/70" />
            </div>
          </div>
        ))}
      </div>
    );
  }

  if (isError) {
    return (
      <div className="flex flex-col items-center gap-3 py-12 text-center px-4">
        <div className="flex h-12 w-12 items-center justify-center rounded-full bg-destructive/10">
          <AlertTriangle className="h-6 w-6 text-destructive" />
        </div>
        <p className="font-medium text-destructive">حدث خطأ أثناء تحميل المحادثات</p>
        <p className="text-sm text-muted-foreground">تحقق من الاتصال ثم أعد المحاولة</p>
        <Button type="button" size="sm" variant="outline" onClick={() => refetch()}>
          إعادة المحاولة
        </Button>
      </div>
    );
  }

  if (items.length === 0) {
    return (
      <EmptyState
        icon={<MessageSquare className="h-10 w-10" />}
        title="لا توجد محادثات بعد"
        description="ابدأ من إعلان أو ملف بائع عبر «راسل البائع» — ستظهر محادثاتك هنا."
        action={
          <div className="flex flex-col items-center gap-2 sm:flex-row">
            <Button asChild size="sm">
              <Link href={`${ROUTES.search}?type=ads`}>تصفّح الإعلانات</Link>
            </Button>
            <Button asChild size="sm" variant="outline">
              <Link href={ROUTES.home}>العودة للرئيسية</Link>
            </Button>
          </div>
        }
      />
    );
  }

  return (
    <div className="flex flex-col rounded-xl bg-card shadow-sm overflow-hidden md:rounded-none md:shadow-none md:h-full">
      {/* Desktop sticky header */}
      <div className="hidden md:flex sticky top-0 z-10 flex-col gap-2 border-b bg-card/95 backdrop-blur-sm px-3 py-3">
        <div className="flex items-center justify-between gap-2 px-1">
          <h2 className="text-sm font-semibold">الرسائل</h2>
          {totalUnread > 0 && (
            <span className="rounded-full bg-primary/10 px-2 py-0.5 text-[11px] font-semibold text-primary">
              {totalUnread} غير مقروءة
            </span>
          )}
        </div>
        <div className="relative">
          <Search className="pointer-events-none absolute start-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
          <input
            type="search"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="بحث في المحادثات…"
            className="w-full rounded-full border bg-muted/50 py-2 pe-9 ps-9 text-sm outline-none transition-colors placeholder:text-muted-foreground focus:border-primary/40 focus:bg-background focus:ring-2 focus:ring-primary/15"
            aria-label="بحث في المحادثات"
          />
          {query && (
            <button
              type="button"
              onClick={() => setQuery('')}
              className="absolute end-2 top-1/2 flex h-7 w-7 -translate-y-1/2 items-center justify-center rounded-full text-muted-foreground hover:bg-muted hover:text-foreground"
              aria-label="مسح البحث"
            >
              <X className="h-3.5 w-3.5" />
            </button>
          )}
        </div>
      </div>

      {/* Mobile search */}
      <div className="md:hidden border-b px-3 py-2">
        <div className="relative">
          <Search className="pointer-events-none absolute start-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
          <input
            type="search"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="بحث…"
            className="w-full rounded-full border bg-muted/40 py-2 pe-3 ps-9 text-sm outline-none focus:border-primary/40 focus:ring-2 focus:ring-primary/15"
            aria-label="بحث في المحادثات"
          />
        </div>
      </div>

      {filtered.length === 0 ? (
        <div className="flex flex-col items-center gap-2 py-12 px-4 text-center">
          <Search className="h-8 w-8 text-muted-foreground/60" />
          <p className="text-sm font-medium">لا نتائج لـ «{query}»</p>
          <button type="button" onClick={() => setQuery('')} className="text-sm text-primary hover:underline">
            مسح البحث
          </button>
        </div>
      ) : (
        <div className="flex flex-col md:overflow-y-auto md:flex-1">
          {filtered.map((conversation, index) => {
            const party = otherParty(conversation, user?.id);
            const avatar = getAvatarUrl(party.avatarUrl ?? '', 56);
            const isSelected = conversation.id === selectedId;
            const hasUnread = conversation.unreadCount > 0;
            const ctx = contextLabel(conversation);
            const isLast = index === filtered.length - 1;

            return (
              <Link
                key={conversation.id}
                href={ROUTES.conversationDetail(conversation.id)}
                aria-current={isSelected ? 'page' : undefined}
                className={cn(
                  'group relative flex items-center gap-3 px-4 py-3.5 transition-colors active:scale-[0.99] touch-manipulation',
                  'hover:bg-muted/50',
                  isSelected && 'bg-primary/5 hover:bg-primary/8 dark:bg-primary/10 dark:hover:bg-primary/15',
                  hasUnread && !isSelected && 'bg-primary/[0.03]',
                )}
              >
                {/* Selected accent bar (RTL-aware via border-s) */}
                {isSelected && (
                  <span className="absolute inset-y-2 start-0 w-1 rounded-e-full bg-primary" aria-hidden />
                )}

                <div className="relative shrink-0">
                  <div
                    className={cn(
                      'relative h-14 w-14 overflow-hidden rounded-full bg-muted shadow-sm',
                      isSelected ? 'ring-2 ring-primary/30' : 'ring-2 ring-card',
                    )}
                  >
                    <SafeImage
                      variant="avatar"
                      src={avatar}
                      alt={party.name}
                      fill
                      className="object-cover"
                      sizes="56px"
                    />
                  </div>
                  {onlineMap?.[party.id] && (
                    <span
                      className="absolute bottom-0 end-0 h-3.5 w-3.5 rounded-full bg-online ring-2 ring-card"
                      aria-label="متصل الآن"
                      title="متصل الآن"
                    />
                  )}
                  {hasUnread && (
                    <span
                      className="absolute -top-1 -end-1 flex h-5 min-w-5 items-center justify-center rounded-full bg-primary px-1 text-[11px] font-semibold text-primary-foreground ring-2 ring-card"
                      aria-label={`${conversation.unreadCount} رسالة غير مقروءة`}
                    >
                      {conversation.unreadCount > 9 ? '9+' : conversation.unreadCount}
                    </span>
                  )}
                </div>

                <div className="min-w-0 flex-1">
                  <div className="mb-0.5 flex items-baseline justify-between gap-2">
                    <p
                      className={cn(
                        'text-sm line-clamp-1',
                        hasUnread ? 'font-bold text-foreground' : 'font-semibold text-foreground/90',
                      )}
                    >
                      {party.name}
                    </p>
                    <span
                      className={cn(
                        'shrink-0 text-[11px] tabular-nums',
                        hasUnread ? 'font-semibold text-primary' : 'text-muted-foreground',
                      )}
                    >
                      {formatRelativeTime(conversation.updatedAt)}
                    </span>
                  </div>

                  <p
                    className={cn(
                      'text-xs line-clamp-1 leading-relaxed',
                      hasUnread ? 'font-medium text-foreground/80' : 'text-muted-foreground',
                    )}
                  >
                    {previewText(conversation, user?.id)}
                  </p>

                  {ctx && conversation.lastMessage && (
                    <p className="mt-1 line-clamp-1 text-[10px] text-muted-foreground/80">
                      بخصوص: {ctx}
                    </p>
                  )}
                </div>

                {!isLast && <div className="absolute bottom-0 inset-x-4 h-px bg-border/80" />}
              </Link>
            );
          })}

          {hasMore && !query.trim() && (
            <div className="flex justify-center border-t p-3">
              <Button
                variant="ghost"
                size="sm"
                disabled={loadingMore}
                onClick={() => setLimit((l) => l + PAGE_SIZE)}
                className="gap-2"
              >
                {loadingMore ? <Loader2 className="h-4 w-4 animate-spin" /> : null}
                تحميل المزيد
              </Button>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

'use client';

import { useState, useEffect, useRef, type FormEvent } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import { Search, Clock } from 'lucide-react';

import { Input } from '@/components/shared/ui/Input';
import { Button } from '@/components/shared/ui/Button';
import { SearchSuggestions } from '@/components/search/SearchSuggestions';
import { ROUTES } from '@/lib/constants';
import { cn } from '@/lib/utils';
import {
  addRecentSearch,
  getRecentSearches,
  clearRecentSearches,
} from '@/lib/recentSearches';

interface Props {
  defaultValue?: string;
  /** Applied to the underlying Input — e.g. light-on-dark styling when rendered on a tinted band. */
  inputClassName?: string;
}

/**
 * Unified search box — suggestions + recent local history when the
 * field is focused with an empty / short query.
 */
export function SearchBox({ defaultValue = '', inputClassName }: Props) {
  const router = useRouter();
  const sp = useSearchParams();
  const [value, setValue] = useState(defaultValue);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [recent, setRecent] = useState<string[]>([]);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    setRecent(getRecentSearches());
  }, []);

  // DESKTOP-AUDIT-03: GlobalSearchShortcut (Ctrl/Cmd+K) appends
  // ?focus=1 when it navigates here from elsewhere in the app — this
  // is the one SearchBox instance that route actually renders
  // (app/(public)/search/page.tsx). Focus the field, then strip the
  // param via router.replace so it doesn't linger in the URL bar or
  // get re-triggered on a manual refresh/back-navigation.
  useEffect(() => {
    if (sp.get('focus') !== '1') return;
    inputRef.current?.focus();
    const params = new URLSearchParams(sp.toString());
    params.delete('focus');
    const query = params.toString();
    router.replace(query ? `${ROUTES.search}?${query}` : ROUTES.search);
    // Only ever meant to run once per navigation that carries the
    // param — deliberately not depending on `sp`/`router` themselves,
    // which would re-fire this on every param change this effect
    // itself just made.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  function navigate(q: string) {
    const params = new URLSearchParams(sp.toString());
    const trimmed = q.trim();
    if (trimmed) {
      params.set('q', trimmed);
      addRecentSearch(trimmed);
      setRecent(getRecentSearches());
    } else {
      params.delete('q');
    }
    params.delete('page');
    router.push(`${ROUTES.search}?${params.toString()}`);
  }

  function handleSubmit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setShowSuggestions(false);
    navigate(value);
  }

  function handleSelectSuggestion(suggestion: string) {
    setValue(suggestion);
    setShowSuggestions(false);
    navigate(suggestion);
  }

  const trimmed = value.trim();
  const showRecent = showSuggestions && trimmed.length < 2 && recent.length > 0;

  return (
    <div className="relative w-full">
      <form onSubmit={handleSubmit} role="search" className="flex w-full gap-2">
        <div className="relative flex-1">
          <Search className="pointer-events-none absolute start-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
          <Input
            ref={inputRef}
            id="global-search-input"
            type="search"
            value={value}
            onChange={(e) => {
              setValue(e.target.value);
              setShowSuggestions(true);
            }}
            onFocus={() => {
              setRecent(getRecentSearches());
              setShowSuggestions(true);
            }}
            onBlur={() => setTimeout(() => setShowSuggestions(false), 150)}
            placeholder="ابحث عن منتجات، محلات، إعلانات، خدمات..."
            className={cn('ps-9', inputClassName)}
            aria-label="بحث"
            autoComplete="off"
          />
        </div>
        <Button type="submit">بحث</Button>
      </form>

      {showRecent && (
        <div
          role="listbox"
          aria-label="عمليات البحث الأخيرة"
          className="absolute inset-x-0 top-full z-[100] mt-1 overflow-hidden rounded-lg border bg-popover text-popover-foreground shadow-lg"
        >
          <div className="flex items-center justify-between border-b px-3 py-1.5">
            <span className="text-xs font-medium text-muted-foreground">عمليات البحث الأخيرة</span>
            <button
              type="button"
              className="text-xs text-muted-foreground hover:text-foreground"
              onClick={() => {
                clearRecentSearches();
                setRecent([]);
              }}
            >
              مسح
            </button>
          </div>
          <ul>
            {recent.map((item) => (
              <li key={item}>
                <button
                  type="button"
                  role="option"
                  className="flex w-full items-center gap-2 px-3 py-2.5 text-start text-sm hover:bg-muted min-h-[44px]"
                  onMouseDown={(e) => e.preventDefault()}
                  onClick={() => handleSelectSuggestion(item)}
                >
                  <Clock className="h-3.5 w-3.5 shrink-0 text-muted-foreground" aria-hidden />
                  <span className="truncate">{item}</span>
                </button>
              </li>
            ))}
          </ul>
        </div>
      )}

      {showSuggestions && trimmed.length >= 2 && (
        <SearchSuggestions query={value} onSelect={handleSelectSuggestion} />
      )}
    </div>
  );
}

'use client';

import Link from 'next/link';
import { useEffect, useMemo, useState } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import { Search } from 'lucide-react';
import { UnifiedResultCard } from '@/components/search/UnifiedResultCard';
import { Pagination } from '@/components/shared/ui/Pagination';
import { AdCardSkeleton } from '@/components/shared/skeletons/AdCardSkeleton';
import { EmptySearchSuggestions } from '@/components/search/EmptySearchSuggestions';
import { EmptySearchAlternatives } from '@/components/search/EmptySearchAlternatives';
import { EmptyState } from '@/components/shared/feedback/EmptyState';
import { Button } from '@/components/shared/ui/Button';
import { SaveSearchButton } from '@/components/ads/SaveSearchButton';
import { useSearch } from '@/hooks/queries/useSearch';
import { useProgressiveSearchRadius } from '@/hooks/queries/useProgressiveSearchRadius';
import { useOnlineStatus } from '@/hooks/useOnlineStatus';
import { LocationSourceBadge } from '@/components/home/LocationSourceBadge';
import { formatRadiusLabel } from '@/lib/progressiveRadius';
import { ROUTES } from '@/lib/constants';
import { track } from '@/lib/analytics';
import type { SearchSort, SearchType } from '@/types/search.types';
import { SearchViewToggle, type SearchViewMode } from '@/components/search/SearchViewToggle';
import { SearchResultsMap } from '@/components/map/SearchResultsMap';

/**
 * Unified results grid — reads q/city/type/categoryId/sort/page
 * straight from the URL (same "URL is the source of truth" convention
 * SearchResults.tsx already uses for the ads-only search page), so
 * SearchTabs/city filter/sort control all just push a new URL rather
 * than lifting shared state up through props.
 */
export function SearchResults() {
  const sp = useSearchParams();
  const router = useRouter();
  const isOnline = useOnlineStatus();

  const q          = sp.get('q') ?? undefined;
  const city       = sp.get('city') ?? undefined;
  const type       = (sp.get('type') as SearchType) ?? 'all';
  const categoryId = sp.get('categoryId') ?? undefined;
  const sort       = (sp.get('sort') as SearchSort) ?? 'relevance';
  const page       = Number(sp.get('page') ?? 1);
  // TRACK-NEARBY-SEARCH: lat/lng/radius live in the URL like every
  // other filter on this page (SearchNearbyToggle writes them via
  // router.push, the same "URL is the source of truth" convention
  // SearchFilters/SearchTabsWrapper already use) — unlike
  // NearbyServiceProviders.tsx's local useState, this page's filters/
  // sort/pagination are already URL-driven, so geo belongs there too
  // rather than introducing a second, inconsistent state mechanism.
  const latParam    = sp.get('lat');
  const lngParam    = sp.get('lng');
  const lat         = latParam !== null ? Number(latParam) : undefined;
  const lng         = lngParam !== null ? Number(lngParam) : undefined;
  const radiusParam = sp.get('radius');
  const radius      = radiusParam !== null ? Number(radiusParam) : undefined;

  // توسيع تدريجي عندما يتوفر GPS ولم يُحدَّد radius يدويًا وليس هناك مدينة
  const progressive = useProgressiveSearchRadius({
    enabled: lat !== undefined && lng !== undefined,
    lat,
    lng,
    explicitRadius: radius,
    type,
    q,
    city,
    categoryId,
    sort: lat !== undefined ? 'distance' : sort,
    limit: 12,
  });

  const effectiveRadius =
    radius !== undefined && !Number.isNaN(radius)
      ? radius
      : progressive.radiusKm ?? undefined;

  const effectiveSort: SearchSort =
    lat !== undefined && lng !== undefined && (sort === 'relevance' || sort === 'distance')
      ? 'distance'
      : sort;

  // UX-FIX (audit P2-02): mirrors exactly what SearchFilters.tsx's own
  // reset button clears (city/categoryId/sort/geo — q is deliberately
  // preserved by that button, so it's not "active" in this sense).
  const hasActiveFilters = Boolean(city || categoryId || (sort && sort !== 'relevance') || lat !== undefined);

  const { data, isLoading: searchLoading, isError, refetch } = useSearch({
    q,
    city,
    type,
    categoryId,
    sort: effectiveSort,
    page,
    lat,
    lng,
    radius: effectiveRadius,
  });

  const isLoading = searchLoading || (Boolean(lat !== undefined && lng !== undefined) && !progressive.resolved);

  const items      = data?.items ?? [];

  const [viewMode, setViewMode] = useState<SearchViewMode>('list');
  const userLocation =
    lat !== undefined && lng !== undefined
      ? { lat: Number(lat), lng: Number(lng) }
      : null;
  const mapPoints = useMemo(
    () =>
      items
        .filter((r) => r.latitude != null && r.longitude != null)
        .map((r) => ({
          id: `${r.type}-${r.id}`,
          title: r.title,
          lat: Number(r.latitude),
          lng: Number(r.longitude),
          href: r.url,
          subtitle: r.city ?? undefined,
        })),
    [items]
  );
  const totalPages = data?.meta?.totalPages ?? 1;
  const total      = data?.meta?.total ?? 0;

  const searchParams = Object.fromEntries(sp.entries());

  // Gap #7 (product analytics): fires once per resolved query — depends
  // on the actual query params (not `data`) so it doesn't re-fire on
  // background refetches of the same search, only when the visitor
  // issues a (possibly) different one. Only tracks non-empty queries —
  // landing on /search with no `q` yet isn't a search event.
  useEffect(() => {
    if (q) track('SEARCH', { q, city, type, categoryId, resultCount: data?.meta?.total });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [q, city, type, categoryId, page]);

  if (isLoading) {
    // FIX AUDIT-2: was a single centered LoadingSpinner that replaced
    // the whole results area, discarding the grid shape on every
    // filter/page/search change — the older ads-only SearchResults.tsx
    // already reuses AdCardSkeleton for exactly this; UnifiedResultCard
    // shares that same outer shape (rounded-xl border bg-card), so the
    // same skeleton fits here without introducing a new one.
    return (
      <div className="space-y-4">
        <div className="h-5 w-32 rounded bg-muted animate-pulse" />
        {/* UX-FIX: this grid sits in a 3-of-4-column <main> next to the
            filters <aside> (see (public)/search/page.tsx), so it had
            real width to work with but was capped at xl:grid-cols-3 —
            stuck at just 2 columns for the whole lg range (1024–1279px,
            a very common desktop width) despite the space, while every
            other ad grid in the app (RecentAds/FeaturedAds/etc.) reaches
            4 columns. Same fix mirrored below and in ads/SearchResults.tsx
            (categories/[slug] uses the identical 1-col-sidebar layout). */}
        <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-5 gap-4">
          {Array.from({ length: 9 }).map((_, i) => <AdCardSkeleton key={i} />)}
        </div>
      </div>
    );
  }

  if (isError) {
    // FIX SEARCH-OFFLINE-01: useSearch already falls back to a local
    // substring index (lib/offlineSearchIndex.ts's searchOffline) built
    // from CORE_CACHE when the network request fails — q/city/type
    // filters DO match offline as long as a core bundle was ever warmed
    // (see offlineCoreBundle.ts). isError here therefore does NOT mean
    // "this specific search has filters" — searchOffline returns a
    // normal (possibly empty) result whenever hasBundle is true,
    // regardless of filters, and that path never reaches this branch at
    // all. isError only fires when either (a) it's a genuine online
    // server error, or (b) hasBundle is false — no core bundle has ever
    // been cached (e.g. app opened for the first time while offline, or
    // storage was cleared) — in which case there's nothing local to
    // fall back to no matter what the user searches for. The generic
    // "حدث خطأ أثناء تحميل النتائج" + a "إعادة المحاولة" button that
    // cannot succeed offline didn't distinguish this case at all.
    if (!isOnline) {
      return (
        <div className="flex flex-col items-center gap-3 py-12 text-center">
          <p className="text-destructive">البحث يحتاج اتصال بالإنترنت</p>
          <p className="max-w-xs text-sm text-muted-foreground">
            لا توجد بيانات محفوظة على الجهاز للبحث بدون نت بعد. افتح التطبيق
            وأنت متصل مرة واحدة على الأقل ليتوفر بحث أساسي لاحقًا بدون اتصال.
          </p>
          <button type="button" onClick={() => refetch()} className="text-sm text-primary hover:underline">
            إعادة المحاولة
          </button>
        </div>
      );
    }

    return (
      <div className="flex flex-col items-center gap-3 py-12 text-center">
        <p className="text-destructive">حدث خطأ أثناء تحميل النتائج</p>
        <button type="button" onClick={() => refetch()} className="text-sm text-primary hover:underline">
          إعادة المحاولة
        </button>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {lat !== undefined && lng !== undefined && effectiveRadius != null && (
        <div className="flex flex-wrap items-center gap-2">
          <LocationSourceBadge source="gps" radiusKm={effectiveRadius} />
          <span className="text-xs text-muted-foreground">
            أقرب النتائج أولًا — {formatRadiusLabel(Number(effectiveRadius))}
          </span>
        </div>
      )}

      {/* Toolbar — same "count on the left, save-search on the right"
          pattern as ads/SearchResults.tsx (categories/[slug] page), so
          the action is available on the main /search page too and not
          just when arriving via a category. SaveSearchButton reads the
          URL's own filter params independently, so it doesn't need any
          props threaded through from here. */}
      {/* Toolbar — save-search only makes sense once the visitor has
          narrowed to one matchable entity kind, OR picks one inside
          the button itself. type='all' mixes ads/products/stores/
          services in one grid with no single filter shape to store
          server-side, so SaveSearchButton now asks which kind to save
          as when `type` is omitted (see its own TYPE-PICK-STEP doc)
          rather than hiding entirely on "الكل". 'stores' still has no
          entry point at all — stores.service.ts's createStore doesn't
          call savedSearchEvents, unlike ads/products/services, so
          there is no matcher a stores-typed SavedSearch could ever
          fire against. */}
      <div className="flex flex-wrap items-center justify-between gap-2">
        <p className="text-sm text-muted-foreground" role="status" aria-live="polite" aria-atomic="true">
          {total > 0 ? `${total} نتيجة` : 'لا توجد نتائج'}
          {q && (
            <>
              {' '}
              بحثاً عن «<span className="font-medium text-foreground">{q}</span>»
            </>
          )}
        </p>
        <div className="flex items-center gap-2">
          <SearchViewToggle value={viewMode} onChange={setViewMode} />
          {type !== 'stores' && (
            <SaveSearchButton type={type === 'all' ? undefined : type} queryParamKey="q" />
          )}
        </div>
      </div>

      {items.length === 0 ? (
        <>
        {/* Empty state + category escape hatches */}
        <EmptyState
          icon={<Search className="h-10 w-10" />}
          title={q ? `لا نتائج لـ «${q}»` : 'لا توجد نتائج'}
          description={
            q
              ? 'جرّب كلمة أقصر، أو امسح الفلاتر، أو اختر تصنيفاً من الاقتراحات بالأسفل.'
              : 'لا توجد نتائج مطابقة لهذه الفلاتر. وسّع النطاق أو اختر نوعاً آخر.'
          }
          action={
            <div className="flex flex-col items-center gap-2 sm:flex-row">
              {(hasActiveFilters || q) && (
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() =>
                    router.push(
                      hasActiveFilters && q
                        ? `${ROUTES.search}?q=${encodeURIComponent(q)}`
                        : ROUTES.search,
                    )
                  }
                >
                  {hasActiveFilters ? 'مسح الفلاتر' : 'عرض كل النتائج'}
                </Button>
              )}
              <Button variant="default" size="sm" asChild>
                <Link href={ROUTES.adCreate}>انشر إعلاناً بدلاً من ذلك</Link>
              </Button>
            </div>
          }
        />
        <EmptySearchSuggestions />
        <EmptySearchAlternatives />
        </>
      ) : (
        <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-5 gap-4 stagger-fade-in">
          {viewMode === 'map' ? (
            <div className="col-span-full">
              <SearchResultsMap points={mapPoints} userLocation={userLocation} />
            </div>
          ) : (
            items.map((result) => (
              <UnifiedResultCard key={`${result.type}-${result.id}`} result={result} />
            ))
          )}
        </div>
      )}

      {totalPages > 1 && (
        <Pagination
          totalPages={totalPages}
          currentPage={page}
          baseUrl={ROUTES.search}
          searchParams={searchParams}
        />
      )}
    </div>
  );
}

'use client';

import { useState } from 'react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { SafeImage } from '@/components/shared/ui/SafeImage';
import {
  Pencil,
  Trash2,
  Eye,
  Briefcase,
  AlertTriangle,
  Pause,
  Play,
  Search,
  Inbox,
  CalendarClock,
} from 'lucide-react';
import { Button } from '@/components/shared/ui/Button';
import { Badge } from '@/components/shared/ui/Badge';
import { Input } from '@/components/shared/ui/Input';
import { Pagination } from '@/components/shared/ui/Pagination';
import { EmptyState } from '@/components/shared/feedback/EmptyState';
import { AdListItemSkeleton } from '@/components/shared/skeletons/AdListItemSkeleton';
import { ConfirmDialog } from '@/components/shared/feedback/ConfirmDialog';
import { useMyServiceListings } from '@/hooks/queries/useServiceListings';
import { useMyServiceProvider } from '@/hooks/queries/useServiceProviders';
import {
  useDeleteServiceListing,
  useToggleServiceListingStatus,
} from '@/hooks/mutations/useServiceListingMutations';
import { useOwnedListPage, useOutOfRangeRedirect } from '@/hooks/useOwnedListPage';
import { ROUTES } from '@/lib/constants';
import { formatPrice, formatRelativeTime } from '@/lib/formatters';
import { getThumbnailUrl, PLACEHOLDER_SVG } from '@/lib/cloudinary';
import type { ServiceListingStatus, ServicePricingType } from '@/types/service.types';

const STATUS_LABELS: Record<ServiceListingStatus, string> = {
  ACTIVE: 'نشطة',
  PAUSED: 'متوقفة',
  DELETED: 'محذوفة',
};

function formatServicePrice(pricingType: ServicePricingType, price: string | null): string {
  if (pricingType === 'NEGOTIABLE' || !price) return 'حسب الاتفاق';
  const formatted = formatPrice(price);
  return pricingType === 'STARTING_FROM' ? `يبدأ من ${formatted}` : formatted;
}

export function MyServiceListingsList() {
  const router = useRouter();
  const { data: provider, isSuccess: providerOk } = useMyServiceProvider();
  const { page, status, setStatus, searchParams: sp } = useOwnedListPage<ServiceListingStatus>(
    ROUTES.myServices,
  );
  const searchQ = sp.get('q') ?? '';
  const [searchInput, setSearchInput] = useState(searchQ);

  const hasProvider = providerOk && Boolean(provider);
  const { data, isLoading, isError, refetch } = useMyServiceListings(
    {
      page,
      limit: 10,
      status,
      search: searchQ || undefined,
    },
    { enabled: hasProvider },
  );

  // Hub shows BecomeServiceProviderCard; hide list until a provider exists.
  if (!hasProvider) return null;
  const deleteListing = useDeleteServiceListing();
  const toggleStatus = useToggleServiceListingStatus();

  const [deleteTargetId, setDeleteTargetId] = useState<string | null>(null);
  const [selected, setSelected] = useState<Set<string>>(new Set());

  const items = data?.items ?? [];
  const totalPages = data?.meta?.totalPages ?? 1;

  const isOutOfRange = useOutOfRangeRedirect({
    baseUrl: ROUTES.myServices,
    page,
    totalPages: data?.meta?.totalPages,
    hasData: !!data,
    searchParams: sp,
  });

  function pushParams(mutator: (params: URLSearchParams) => void) {
    const params = new URLSearchParams(sp.toString());
    mutator(params);
    params.delete('page');
    router.push(`${ROUTES.myServices}?${params.toString()}`);
  }

  function submitSearch(e: React.FormEvent) {
    e.preventDefault();
    pushParams((params) => {
      const q = searchInput.trim();
      if (q) params.set('q', q);
      else params.delete('q');
    });
  }

  function toggleSelect(id: string) {
    setSelected((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  }

  async function bulkStatus(next: 'ACTIVE' | 'PAUSED') {
    for (const id of selected) {
      await toggleStatus.mutateAsync({ id, status: next });
    }
    setSelected(new Set());
  }

  if (isLoading || isOutOfRange) {
    return (
      <div className="space-y-3">
        {Array.from({ length: 5 }).map((_, i) => (
          <AdListItemSkeleton key={i} />
        ))}
      </div>
    );
  }

  if (isError) {
    return (
      <div className="flex flex-col items-center gap-3 py-12 text-center">
        <AlertTriangle className="h-10 w-10 text-muted-foreground" />
        <p className="text-destructive">حدث خطأ أثناء تحميل خدماتك</p>
        <button type="button" onClick={() => refetch()} className="text-sm text-primary hover:underline">
          إعادة المحاولة
        </button>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between gap-2 flex-wrap">
        <h2 className="text-sm font-semibold text-muted-foreground">قائمة الخدمات</h2>
        <Link href={ROUTES.myServiceCreate}>
          <Button size="sm">خدمة جديدة</Button>
        </Link>
      </div>

      <form onSubmit={submitSearch} className="flex gap-2">
        <div className="relative flex-1">
          <Search className="absolute start-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
          <Input
            value={searchInput}
            onChange={(e) => setSearchInput(e.target.value)}
            placeholder="ابحث بعنوان الخدمة…"
            className="ps-9"
            aria-label="بحث في الخدمات"
          />
        </div>
        <Button type="submit" variant="secondary">
          بحث
        </Button>
      </form>

      <div
        className="flex gap-2 border-b pb-3 overflow-x-auto"
        role="group"
        aria-label="تصفية الخدمات حسب الحالة"
      >
        {([['', 'الكل'], ['ACTIVE', 'نشطة'], ['PAUSED', 'متوقفة'], ['DELETED', 'محذوفة']] as const).map(
          ([val, label]) => (
            <button
              key={val}
              type="button"
              onClick={() => setStatus(val)}
              aria-pressed={(status ?? '') === val}
              className={`shrink-0 text-sm px-3 py-1 rounded-full transition-colors ${
                (status ?? '') === val
                  ? 'bg-primary text-primary-foreground'
                  : 'hover:bg-muted text-muted-foreground'
              }`}
            >
              {label}
            </button>
          ),
        )}
      </div>

      {selected.size > 0 && (
        <div className="flex flex-wrap items-center gap-2 rounded-lg border bg-muted/40 p-2 text-sm">
          <span className="font-medium">{selected.size} محدد</span>
          <Button
            size="sm"
            variant="outline"
            onClick={() => bulkStatus('ACTIVE')}
            disabled={toggleStatus.isPending}
          >
            تفعيل
          </Button>
          <Button
            size="sm"
            variant="outline"
            onClick={() => bulkStatus('PAUSED')}
            disabled={toggleStatus.isPending}
          >
            إيقاف
          </Button>
          <Button type="button" size="sm" variant="ghost" onClick={() => setSelected(new Set())}>
            إلغاء التحديد
          </Button>
        </div>
      )}

      {items.length === 0 ? (
        <EmptyState
          icon={<Briefcase className="h-10 w-10" />}
          title={searchQ ? 'لا نتائج لهذا البحث' : 'لا توجد خدمات'}
          description={
            searchQ
              ? 'جرّب تغيير كلمة البحث أو فلاتر الحالة'
              : 'أضف خدمة ثم تابع الطلبات الواردة واحجز المواعيد مع العملاء'
          }
          action={
            <div className="flex flex-col sm:flex-row gap-2 items-center">
              <Link href={ROUTES.myServiceCreate}>
                <Button>إضافة خدمة</Button>
              </Link>
              {!searchQ && (
                <>
                  <Link href={ROUTES.incomingServiceRequests}>
                    <Button variant="outline" className="gap-1.5">
                      <Inbox className="h-4 w-4" /> الطلبات
                    </Button>
                  </Link>
                  <Link href={ROUTES.myServiceAppointments}>
                    <Button variant="outline" className="gap-1.5">
                      <CalendarClock className="h-4 w-4" /> المواعيد
                    </Button>
                  </Link>
                </>
              )}
            </div>
          }
        />
      ) : (
        <div className="space-y-3">
          {items.map((listing) => {
            const thumb = listing.images[0]
              ? getThumbnailUrl(listing.images[0], 120, 90)
              : PLACEHOLDER_SVG;
            return (
              <div key={listing.id} className="flex gap-3 p-3 rounded-lg border bg-card">
                {listing.status !== 'DELETED' && (
                  <input
                    type="checkbox"
