                  </Link>
                  {listing.status !== 'DELETED' && (
                    <Button
                      variant="ghost"
                      size="icon"
                      className="h-10 w-10"
                      aria-label={
                        listing.status === 'PAUSED'
                          ? `إعادة تفعيل ${listing.title}`
                          : `إيقاف ${listing.title} مؤقتاً`
                      }
                      title={listing.status === 'PAUSED' ? 'إعادة تفعيل' : 'إيقاف مؤقت'}
                      disabled={toggleStatus.isPending && toggleStatus.variables?.id === listing.id}
                      onClick={() =>
                        toggleStatus.mutate({
                          id: listing.id,
                          status: listing.status === 'PAUSED' ? 'ACTIVE' : 'PAUSED',
                        })
                      }
                    >
                      {listing.status === 'PAUSED' ? (
                        <Play className="h-3.5 w-3.5 text-success" />
                      ) : (
                        <Pause className="h-3.5 w-3.5" />
                      )}
                    </Button>
                  )}
                  <Button
                    variant="ghost"
                    size="icon"
                    className="h-10 w-10 text-destructive hover:text-destructive"
                    aria-label={`حذف ${listing.title}`}
                    onClick={() => setDeleteTargetId(listing.id)}
                  >
                    <Trash2 className="h-3.5 w-3.5" />
                  </Button>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {totalPages > 1 && (
        <Pagination
          totalPages={totalPages}
          currentPage={page}
          baseUrl={ROUTES.myServices}
          searchParams={Object.fromEntries(sp.entries())}
        />
      )}

      <ConfirmDialog
        open={deleteTargetId !== null}
        onOpenChange={(open) => {
          if (!open) setDeleteTargetId(null);
        }}
        title="حذف الخدمة؟"
        description="لا يمكن التراجع عن هذا الإجراء بعد التأكيد."
        confirmLabel="حذف"
        destructive
        isPending={deleteListing.isPending}
        onConfirm={() => {
          if (!deleteTargetId) return;
          deleteListing.mutate(deleteTargetId, { onSuccess: () => setDeleteTargetId(null) });
        }}
      />
    </div>
  );
}

'use client';

/**
 * إدارة المخزون — جدول منتجات المتجر مع تعديل كمية سريع.
 * يعتمد على GET /products/me + PATCH /products/:id/stock
 */

import { useMemo, useState } from 'react';
import Link from 'next/link';
import { useRouter, useSearchParams } from 'next/navigation';
import { Package, AlertTriangle, Pencil } from 'lucide-react';
import { useMyProducts } from '@/hooks/queries/useProducts';
import { useAdjustProductStock } from '@/hooks/mutations/useAdjustProductStock';
import { Button } from '@/components/shared/ui/Button';
import { Input } from '@/components/shared/ui/Input';
import { Badge } from '@/components/shared/ui/Badge';
import { EmptyState } from '@/components/shared/feedback/EmptyState';
import { LoadingSpinner } from '@/components/shared/feedback/LoadingSpinner';
import { Pagination } from '@/components/shared/ui/Pagination';
import { ROUTES } from '@/lib/constants';
import type { ProductAvailability } from '@/types/product.types';
import { cn } from '@/lib/utils';

const AVAIL_LABELS: Record<ProductAvailability, string> = {
  IN_STOCK: 'متوفر',
  LIMITED: 'منخفض',
  OUT_OF_STOCK: 'نافد',
};

type StockFilter = 'all' | 'low' | 'out';

function stockBadgeVariant(a: ProductAvailability): 'success' | 'warning' | 'destructive' | 'secondary' {
  if (a === 'IN_STOCK') return 'success';
  if (a === 'LIMITED') return 'warning';
  if (a === 'OUT_OF_STOCK') return 'destructive';
  return 'secondary';
}

function StockRow({
  id,
  name,
  stockQuantity,
  availability,
  status,
}: {
  id: string;
  name: string;
  stockQuantity: number | null;
  availability: ProductAvailability;
  status: string;
}) {
  const adjust = useAdjustProductStock();
  const [value, setValue] = useState(
    stockQuantity != null ? String(stockQuantity) : ''
  );
  const [editing, setEditing] = useState(false);

  function save() {
    const trimmed = value.trim();
    const qty = trimmed === '' ? null : Number(trimmed);
    if (trimmed !== '' && (!Number.isFinite(qty) || qty! < 0 || !Number.isInteger(qty))) {
      return;
    }
    adjust.mutate(
      { id, stockQuantity: qty },
      { onSuccess: () => setEditing(false) }
    );
  }

  function bump(delta: number) {
    const current = stockQuantity ?? 0;
    const next = Math.max(0, current + delta);
    setValue(String(next));
    adjust.mutate({ id, stockQuantity: next });
  }

  return (
    <tr className="border-b last:border-0">
      <td className="px-3 py-3">
        <div className="min-w-0">
          <Link
            href={ROUTES.myStoreProductEdit(id)}
            className="font-medium hover:underline line-clamp-1"
          >
            {name}
          </Link>
          <p className="text-xs text-muted-foreground">{status}</p>
        </div>
      </td>
      <td className="px-3 py-3">
        <Badge variant={stockBadgeVariant(availability)}>
          {AVAIL_LABELS[availability]}
        </Badge>
      </td>
      <td className="px-3 py-3">
        {editing ? (
          <div className="flex items-center gap-1">
            <Input
              type="number"
              min={0}
              className="h-9 w-24"
              value={value}
              onChange={(e) => setValue(e.target.value)}
              autoFocus
              onKeyDown={(e) => {
                if (e.key === 'Enter') save();
                if (e.key === 'Escape') {
                  setValue(stockQuantity != null ? String(stockQuantity) : '');
                  setEditing(false);
                }
              }}
            />
            <Button size="sm" onClick={save} disabled={adjust.isPending}>
              حفظ
            </Button>
          </div>
        ) : (
          <span className="tabular-nums text-sm">
            {stockQuantity != null ? stockQuantity : '—'}
          </span>
        )}
      </td>
      <td className="px-3 py-3">
        <div className="flex flex-wrap items-center gap-1">
          <Button
            type="button"
            size="sm"
            variant="outline"
            className="h-8 w-8 p-0"
            disabled={adjust.isPending}
            onClick={() => bump(-1)}
            aria-label="إنقاص"
          >
            −
          </Button>
          <Button
            type="button"
            size="sm"
            variant="outline"
            className="h-8 w-8 p-0"
            disabled={adjust.isPending}
            onClick={() => bump(1)}
            aria-label="زيادة"
          >
            +
          </Button>
          <Button
            type="button"
            size="sm"
            variant="ghost"
            className="h-8 gap-1 px-2"
            onClick={() => setEditing(true)}
          >
            <Pencil className="h-3.5 w-3.5" />
            تعديل
          </Button>
        </div>
      </td>
    </tr>
  );
}

export function MyStoreInventory() {
  const router = useRouter();
  const sp = useSearchParams();
  const page = Number(sp.get('page') ?? 1);
  const filter = (sp.get('stock') as StockFilter) || 'all';
  const searchQ = sp.get('q') ?? '';
  const [searchInput, setSearchInput] = useState(searchQ);

  // Map UI filter → API availability when possible
  const availability: ProductAvailability | undefined =
    filter === 'out' ? 'OUT_OF_STOCK' : filter === 'low' ? 'LIMITED' : undefined;

  const { data, isLoading, isError, refetch } = useMyProducts({
    page,
    limit: 20,
    availability,
    search: searchQ || undefined,
    // ACTIVE only for operational inventory
    status: 'ACTIVE',
  });

  const items = data?.items ?? [];
  const totalPages = data?.meta?.totalPages ?? 1;

  // Client-side extra filter for "low" if backend LIMITED is enough;
  // also show rows with stockQuantity <= 5 when filter=low as fallback
  const rows = useMemo(() => {
    if (filter !== 'low') return items;
    return items.filter(
      (p) =>
        p.availability === 'LIMITED' ||
        (p.stockQuantity != null && p.stockQuantity > 0 && p.stockQuantity <= 5)
    );
  }, [items, filter]);

  function pushParams(mutator: (params: URLSearchParams) => void) {
    const params = new URLSearchParams(sp.toString());
    mutator(params);
    params.delete('page');
    router.push(`${ROUTES.myStoreInventory}?${params.toString()}`);
  }

  function setFilter(next: StockFilter) {
    pushParams((params) => {
      if (next === 'all') params.delete('stock');
      else params.set('stock', next);
    });
  }

  function submitSearch(e: React.FormEvent) {
    e.preventDefault();
    pushParams((params) => {
      const q = searchInput.trim();
      if (q) params.set('q', q);
      else params.delete('q');
    });
  }

  if (isLoading) {
    return (
      <div className="flex justify-center py-16">
        <LoadingSpinner />
      </div>
    );
  }

  if (isError) {
    return (
      <div className="flex flex-col items-center gap-3 py-12 text-center">
        <AlertTriangle className="h-10 w-10 text-muted-foreground" />
        <p className="text-destructive">تعذّر تحميل المخزون</p>
        <button type="button" className="text-sm text-primary hover:underline" onClick={() => refetch()}>
          إعادة المحاولة
        </button>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <h1 className="text-xl font-bold">إدارة المخزون</h1>
          <p className="text-sm text-muted-foreground">
            عدّل الكميات بسرعة دون فتح صفحة المنتج كاملة
          </p>
        </div>
        <Button asChild size="sm" variant="outline">
          <Link href={ROUTES.myStoreProducts}>كل المنتجات</Link>
        </Button>
      </div>

      <div className="flex flex-wrap items-center gap-2">
        {(
          [
            ['all', 'الكل'],
            ['low', 'منخفض'],
            ['out', 'نافد'],
          ] as const
        ).map(([key, label]) => (
          <button
            key={key}
            type="button"
            onClick={() => setFilter(key)}
            className={cn(
              'rounded-full border px-3 py-1 text-sm transition-colors',
              filter === key
                ? 'border-primary bg-primary/10 text-primary'
                : 'text-muted-foreground hover:text-foreground'
            )}
          >
            {label}
          </button>
        ))}
        <form onSubmit={submitSearch} className="ms-auto flex gap-2">
          <Input
            value={searchInput}
            onChange={(e) => setSearchInput(e.target.value)}
            placeholder="بحث بالاسم…"
            className="h-9 w-44"
          />
          <Button type="submit" size="sm" variant="secondary">
            بحث
          </Button>
        </form>
      </div>

      {rows.length === 0 ? (
        <EmptyState
          icon={<Package className="h-10 w-10" />}
          title="لا منتجات في هذا التصفية"
          description="أضف منتجات من صفحة المنتجات أو غيّر الفلتر."
          action={
            <Button asChild size="sm">
              <Link href={ROUTES.myStoreProductCreate}>إضافة منتج</Link>
            </Button>
          }
        />
      ) : (
        <div className="overflow-x-auto rounded-xl border">
          <table className="w-full min-w-[32rem] text-sm">
            <thead className="bg-muted/50 text-muted-foreground">
              <tr>
                <th className="px-3 py-2 text-start font-medium">المنتج</th>
                <th className="px-3 py-2 text-start font-medium">الحالة</th>
                <th className="px-3 py-2 text-start font-medium">الكمية</th>
                <th className="px-3 py-2 text-start font-medium">إجراءات</th>
              </tr>
            </thead>
            <tbody>
              {rows.map((p) => (
                <StockRow
                  key={p.id}
                  id={p.id}
                  name={p.name}
                  stockQuantity={p.stockQuantity ?? null}
                  availability={p.availability}
                  status={p.status}
                />
              ))}
            </tbody>
          </table>
        </div>
      )}

      {totalPages > 1 && (
        <Pagination
          totalPages={totalPages}
          currentPage={page}
          baseUrl={ROUTES.myStoreInventory}
          searchParams={Object.fromEntries(sp.entries())}
        />
      )}
    </div>
  );
}

'use client';

import { useEffect, useMemo, useRef } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import { Package } from 'lucide-react';
import { ProductCard } from './ProductCard';
import { Pagination } from '@/components/shared/ui/Pagination';
import { LoadingSpinner } from '@/components/shared/feedback/LoadingSpinner';
import { EmptyState } from '@/components/shared/feedback/EmptyState';
import { ProductRecommendations } from '@/components/recommendations/ProductRecommendations';
import { DownloadStoreCatalogButton } from '@/components/stores/DownloadStoreCatalogButton';
import { useProducts } from '@/hooks/queries/useProducts';
import { ROUTES } from '@/lib/constants';
import { track } from '@/lib/analytics';
import { cn } from '@/lib/utils';
import type { ProductSortField } from '@/types/product.types';

interface Props {
  storeId: string;
  /** اسم المتجر لعنوان ملف التحميل — اختياري */
  storeName?: string;
  offersOnly?: boolean;
}

const SORT_OPTIONS: { value: string; label: string; sortBy: ProductSortField; sortOrder: 'asc' | 'desc' }[] = [
  { value: 'newest', label: 'الأحدث', sortBy: 'createdAt', sortOrder: 'desc' },
  { value: 'price_asc', label: 'السعر: الأقل', sortBy: 'price', sortOrder: 'asc' },
  { value: 'price_desc', label: 'السعر: الأعلى', sortBy: 'price', sortOrder: 'desc' },
  { value: 'views', label: 'الأكثر مشاهدة', sortBy: 'views', sortOrder: 'desc' },
];

export function StoreProducts({ storeId, storeName, offersOnly = false }: Props) {
  const router = useRouter();
  const sp = useSearchParams();
  const page = Number(sp.get('productsPage') ?? 1);
  const highlightId = sp.get('product');
  const sortKey = sp.get('sort') ?? 'newest';
  const sortOpt = SORT_OPTIONS.find((o) => o.value === sortKey) ?? SORT_OPTIONS[0]!;
  const highlightRef = useRef<HTMLDivElement>(null);

  const { data, isLoading, isError, refetch } = useProducts({
    storeId,
    page,
    limit: 12,
    sortBy: sortOpt.sortBy,
    sortOrder: sortOpt.sortOrder,
    ...(offersOnly ? { hasPromotion: true } : {}),
  });

  const items = useMemo(() => data?.items ?? [], [data?.items]);
  const totalPages = data?.meta?.totalPages ?? 1;

  const highlightedProduct = useMemo(
    () => items.find((p) => p.id === highlightId) ?? null,
    [items, highlightId],
  );

  useEffect(() => {
    if (highlightedProduct) {
      track('PRODUCT_VIEW', {
        productId: highlightedProduct.id,
        categoryId: highlightedProduct.categoryId,
      });
    }
  }, [highlightedProduct?.id, highlightedProduct?.categoryId]);

  useEffect(() => {
    if (highlightId && highlightRef.current) {
      highlightRef.current.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
  }, [highlightId, items]);

  function setSort(value: string) {
    const params = new URLSearchParams(sp.toString());
    if (value === 'newest') params.delete('sort');
    else params.set('sort', value);
    params.delete('productsPage');
    router.push(`${ROUTES.storeDetail(storeId)}?${params.toString()}`, { scroll: false });
  }

  if (isLoading) {
    return (
      <div className="flex justify-center py-8">
        <LoadingSpinner />
      </div>
    );
  }

  if (isError) {
    return (
      <div className="flex flex-col items-center gap-3 py-8 text-center">
        <p className="text-destructive">حدث خطأ أثناء تحميل المنتجات</p>
        <button type="button" onClick={() => refetch()} className="text-sm text-primary hover:underline">
          إعادة المحاولة
        </button>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div className="flex gap-2 overflow-x-auto pb-1" role="group" aria-label="ترتيب المنتجات">
          {SORT_OPTIONS.map((opt) => (
            <button
              key={opt.value}
              type="button"
              onClick={() => setSort(opt.value)}
              className={cn(
                'shrink-0 rounded-full border px-3 py-1 text-xs transition-colors',
                sortKey === opt.value
                  ? 'border-primary bg-primary/10 text-primary'
                  : 'text-muted-foreground hover:bg-muted',
              )}
            >
              {opt.label}
            </button>
          ))}
        </div>
        {!offersOnly && storeName && (
          <DownloadStoreCatalogButton
            storeId={storeId}
            storeName={storeName}
            variant="outline"
            size="sm"
            className="shrink-0 gap-1.5 rounded-full text-xs"
          />
        )}
      </div>

      {items.length === 0 ? (
        <EmptyState
          icon={<Package className="h-10 w-10" />}
          title={offersOnly ? 'لا عروض نشطة حاليًا' : 'لا توجد منتجات'}
          description={
            offersOnly
              ? 'لم يضف هذا المتجر عروضًا سارية الآن'
              : 'لم يضف هذا المتجر أي منتج بعد'
          }
        />
      ) : (
        <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-4 stagger-fade-in">
          {items.map((product) => (
            <div
              key={product.id}
              ref={product.id === highlightId ? highlightRef : undefined}
              className={
                product.id === highlightId
                  ? 'rounded-xl ring-2 ring-primary ring-offset-2 ring-offset-background transition-all'
                  : undefined
              }
            >
              <ProductCard product={product} storeId={storeId} />
            </div>
          ))}
        </div>
      )}

      {totalPages > 1 && (
        <Pagination
          totalPages={totalPages}
          currentPage={page}
          baseUrl={ROUTES.storeDetail(storeId)}
          searchParams={Object.fromEntries(
            Array.from(sp.entries()).filter(([k]) => k !== 'productsPage'),
          )}
          pageParam="productsPage"
        />
      )}

      {!offersOnly && <ProductRecommendations excludeProductId={highlightedProduct?.id} />}
    </div>
  );
}

