'use client';

import { useEffect, useState } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { blockedUsersApi } from '@/api/blocked-users.api';
import { queryKeys } from '@/lib/queryKeys';
import { CACHE_TTL } from '@/lib/constants';
import { useAuthStore, selectIsAuthenticated } from '@/store/auth.store';
import type { BlockedUsersQuery } from '@/types/blocked-user.types';

/**
 * GET /blocked-users — the caller's blocked users, paginated.
 *
 * Also mirrors this page's rows into the shared blockedUsers.ids() Set
 * as a side effect after the query settles, same as
 * useMyFollowedStores does for queryKeys.stores.followedIds() — that
 * Set is what useIsUserBlocked() below reads reactively, since there's
 * no single GET /blocked-users/:userId/status endpoint.
 */
export function useMyBlockedUsers(params?: BlockedUsersQuery) {
  const isAuthenticated = useAuthStore(selectIsAuthenticated);
  const queryClient = useQueryClient();

  const query = useQuery({
    queryKey: queryKeys.blockedUsers.all(params),
    queryFn: () => blockedUsersApi.getMine(params).then((r) => r.data.data),
    staleTime: CACHE_TTL.favorites,
    enabled: isAuthenticated,
  });

  useEffect(() => {
    const data = query.data;
    if (!data) return;

    queryClient.setQueryData<Set<string>>(queryKeys.blockedUsers.ids(), (prev) => {
      const idSet = new Set(prev ?? []);
      data.items.forEach((row) => idSet.add(row.blockedId));
      return idSet;
    });
  }, [query.data]);

  return query;
}

/**
 * Direct accessor for the blocked-user IDs Set from cache.
 * Non-reactive — use useIsUserBlocked() for reactive per-user checks.
 */
export function getBlockedUserIdsSnapshot(
  qc: ReturnType<typeof useQueryClient>,
): Set<string> {
  return qc.getQueryData<Set<string>>(queryKeys.blockedUsers.ids()) ?? new Set();
}

/**
 * Reactive "have I blocked this user" check for ChatWindow's header
 * action — same shape and reasoning as useIsFollowingStore: fetches the
 * full blocked-users list once (capped at 100, matching the
 * useMyFollowedStores({ limit: 100 }) convention) and checks membership
 * against the shared cache Set, which useToggleUserBlock keeps in sync
 * on every successful toggle.
 */
export function useIsUserBlocked(userId: string): boolean {
  const isAuthenticated = useAuthStore(selectIsAuthenticated);
  const queryClient = useQueryClient();
  useMyBlockedUsers({ limit: 100 });

  const [isBlocked, setIsBlocked] = useState<boolean>(() =>
    getBlockedUserIdsSnapshot(queryClient).has(userId),
  );

  useEffect(() => {
    if (!isAuthenticated) {
      setIsBlocked(false);
      return;
    }

    setIsBlocked(getBlockedUserIdsSnapshot(queryClient).has(userId));

    const cache = queryClient.getQueryCache();
    const unsubscribe = cache.subscribe((event) => {
      const key = event.query.queryKey;
      const idsKey = queryKeys.blockedUsers.ids();
      if (key.length !== idsKey.length || key.some((k: unknown, i: number) => k !== idsKey[i])) return;

      setIsBlocked(getBlockedUserIdsSnapshot(queryClient).has(userId));
    });

    return unsubscribe;
  }, [userId, isAuthenticated, queryClient]);

  return isBlocked;
}

import { GEO_POSITION_OPTIONS, isUsableNearbyCoord } from '@/lib/geo';
'use client';

import { useEffect, useState } from 'react';
import { useNearbyServiceProviders } from './useServiceProviders';
import type { NearbyServiceProvidersParams } from '@/types/service.types';

const RADIUS_KM = 7 /* DEFAULT_NEARBY_RADIUS_KM — وضع غزة */;
const DISPLAY_LIMIT = 8;

type PermissionState = 'checking' | 'granted' | 'not-granted';

/**
 * Home §6/§7: silent variant of the pattern NearbyServiceProviders.tsx
 * uses on /service-providers. That component calls
 * navigator.geolocation.getCurrentPosition() directly on user action,
 * which is correct there (explicit "استخدام موقعي الحالي" button) but
 * wrong for Home — calling getCurrentPosition unconditionally on page
 * load triggers the browser's permission popup for every visitor, even
 * ones who've never granted location access.
 *
 * This hook instead checks the Permissions API first, without
 * prompting: only when the browser reports the geolocation permission
 * is already 'granted' does it call getCurrentPosition (which then
 * resolves silently, no popup, since permission already exists) and
 * feed the position into the existing useNearbyServiceProviders hook.
 * For 'prompt', 'denied', or when the Permissions API itself is
 * unsupported, this returns an inert "not available" result and the
 * caller renders nothing — no popup, no error, no skeleton stuck
 * forever (plan §6).
 */
export function useNearbyServiceProvidersIfGranted() {
  const [permission, setPermission] = useState<PermissionState>('checking');
  const [coords, setCoords] = useState<{ lat: number; lng: number } | null>(null);

  useEffect(() => {
    let cancelled = false;

    // jsdom (and some older browsers) report `'permissions' in navigator`
    // as true while `navigator.permissions` itself is undefined — the
    // `'permissions' in navigator` check alone is not enough, and
    // calling `.query` on undefined used to throw and break the
    // "Permissions API unsupported" unit test.
    if (!navigator.geolocation || typeof navigator.permissions?.query !== 'function') {
      setPermission('not-granted');
      return;
    }

    navigator.permissions
      .query({ name: 'geolocation' })
      .then((status) => {
        if (cancelled) return;

        if (status.state !== 'granted') {
          setPermission('not-granted');
          return;
        }

        // Already granted — getCurrentPosition resolves without a
        // popup here, since permission was granted in a prior visit.
        navigator.geolocation.getCurrentPosition(
          (pos) => {
            if (cancelled) return;
            const lat = pos.coords.latitude;
            const lng = pos.coords.longitude;
            if (!isUsableNearbyCoord(lat, lng)) {
              setPermission('not-granted');
              return;
            }
            setCoords({ lat, lng });
            setPermission('granted');
          },
          () => {
            if (cancelled) return;
            setPermission('not-granted');
          },
          GEO_POSITION_OPTIONS,
        );
      })
      .catch(() => {
        if (!cancelled) setPermission('not-granted');
      });

    return () => {
      cancelled = true;
    };
  }, []);

  const params: NearbyServiceProvidersParams | null =
    permission === 'granted' && coords
      ? { lat: coords.lat, lng: coords.lng, radius: RADIUS_KM, limit: DISPLAY_LIMIT }
      : null;

  const query = useNearbyServiceProviders(params);

  /**
   * available === false means "don't render this section at all" —
   * covers 'checking' (still resolving, no flash of an empty section)
   * and 'not-granted' (prompt/denied/unsupported) alike. Callers
   * should not distinguish further; that's the whole point of §6 —
   * no error, no permission-request UI, just absence.
   */
  return {
    available: permission === 'granted',
    isChecking: permission === 'checking',
    ...query,
  };
}

'use client';

import { useSequentialGeoSearch } from '@/hooks/queries/useSequentialGeoSearch';
import type { SearchType, SearchSort } from '@/types/search.types';

interface Args {
  enabled: boolean;
  lat?: number;
  lng?: number;
  explicitRadius?: number;
  type?: SearchType;
  q?: string;
  city?: string;
  categoryId?: string;
  sort?: SearchSort;
  limit?: number;
}

/**
 * غلاف متوافق مع SearchResults — توسيع متسلسل تحت الغطاء.
 * مع مدينة صريحة أو radius يدوي: لا probing.
 */
export function useProgressiveSearchRadius(args: Args): {
  isLoading: boolean;
  radiusKm: number | null;
  resolved: boolean;
} {
  const {
    enabled,
    lat,
    lng,
    explicitRadius,
    type = 'all',
    q,
    city,
    categoryId,
    limit = 8,
  } = args;

  if (explicitRadius !== undefined && !Number.isNaN(explicitRadius)) {
    return { isLoading: false, radiusKm: explicitRadius, resolved: true };
  }

  const shouldProbe = Boolean(enabled && lat != null && lng != null && !city);

  const geo = useSequentialGeoSearch({
    enabled: shouldProbe,
    lat,
    lng,
    type,
    q,
    categoryId,
    limit,
  });

  if (!shouldProbe) {
    return { isLoading: false, radiusKm: null, resolved: true };
  }

  return {
    isLoading: !geo.settled || geo.isLoading,
    radiusKm: geo.settled ? geo.radiusKm ?? 100 : null,
    resolved: geo.settled,
  };
}

