/** GET /stores/me/followed — the caller's followed stores, paginated. */
export function useMyFollowedStores(params?: { page?: number; limit?: number }) {
  const isAuthenticated = useAuthStore(selectIsAuthenticated);
  const queryClient = useQueryClient();

  const query = useQuery({
    queryKey: queryKeys.stores.followed(params),
    queryFn: () => storesApi.getMyFollowedStores(params).then((r) => r.data.data),
    staleTime: CACHE_TTL.favorites,
    enabled: isAuthenticated,
  });

  // FIX BUG-03: mirrors useFavorites' H-05/API-INT-07 fix exactly — merge
  // this page's followed store ids into the shared followedIds() Set as a
  // pure side effect after the query settles, so useIsFollowingStore()
  // below has something to read reactively without a per-store network
  // call (there's no GET /stores/:id/follow-status endpoint).
  useEffect(() => {
    const data = query.data;
    if (!data) return;

    queryClient.setQueryData<Set<string>>(queryKeys.stores.followedIds(), (prev) => {
      const idSet = new Set(prev ?? []);
      data.items.forEach((row) => idSet.add(row.storeId));
      return idSet;
    });
  }, [query.data]);

  return query;
}

/**
 * Direct accessor for the followed-store IDs Set from cache.
 * Non-reactive — use useIsFollowingStore() for reactive per-store checks.
 */
export function getFollowedStoreIdsSnapshot(
  qc: ReturnType<typeof useQueryClient>,
): Set<string> {
  return qc.getQueryData<Set<string>>(queryKeys.stores.followedIds()) ?? new Set();
}

/**
 * FIX BUG-03: StoreHeader (components/stores/StoreHeader.tsx) always
 * accepted an `isFollowing` prop but no caller ever passed one — the
 * store detail page (app/(public)/stores/[id]/page.tsx) only rendered
 * `<StoreHeader store={store} />`, so the button showed "متابعة" for
 * every user regardless of their actual follow state, and clicking it
 * on a store they already followed silently unfollowed them without
 * the UI ever indicating that had happened.
 *
 * There is no single-store "am I following this" endpoint, so — same
 * reasoning and shape as useIsFavorited — this fetches the full
 * followed-stores list once (capped at the backend's max page size of
 * 100, matching the useFavorites({ limit: 100 }) convention already
 * used elsewhere) and checks membership reactively against the shared
 * cache Set, which useToggleStoreFollow keeps in sync on every
 * successful toggle.
 */
export function useIsFollowingStore(storeId: string): boolean {
  const isAuthenticated = useAuthStore(selectIsAuthenticated);
  const queryClient = useQueryClient();
  useMyFollowedStores({ limit: 100 });

  const [isFollowing, setIsFollowing] = useState<boolean>(() =>
    getFollowedStoreIdsSnapshot(queryClient).has(storeId),
  );

  useEffect(() => {
    if (!isAuthenticated) {
      setIsFollowing(false);
      return;
    }

    setIsFollowing(getFollowedStoreIdsSnapshot(queryClient).has(storeId));

    const cache = queryClient.getQueryCache();
    const unsubscribe = cache.subscribe((event) => {
      const key = event.query.queryKey;
      const idsKey = queryKeys.stores.followedIds();
      if (key.length !== idsKey.length || key.some((k: unknown, i: number) => k !== idsKey[i])) return;

      setIsFollowing(getFollowedStoreIdsSnapshot(queryClient).has(storeId));
    });

    return unsubscribe;
  }, [storeId, isAuthenticated, queryClient]);

  return isFollowing;
}

/**
 * تسجيل الـ Service Worker + إدارة التحديثات + اشتراكات Push.
 *
 * ملاحظة أمنية: لا نخزّن أي Push subscription أو أي token في localStorage —
 * الاشتراك يُرسل مباشرة للباك-إند عبر apiClient (نفس آلية Bearer token +
 * httpOnly cookie المستخدمة في باقي الطلبات، انظر api/client.ts) ولا يُحفظ
 * محليًا إلا الحالة البسيطة (isSubscribed: boolean) للتحكم في واجهة الزر.
 */

import { apiClient } from '@/api/client';

// FIX PWA-05: previously read once as a module-level constant
// (`const VAPID_PUBLIC_KEY = process.env...`), which freezes the value at
// import time. In Next.js NEXT_PUBLIC_* vars are inlined at build time so
// this is harmless in production, but it silently breaks anything that
// needs the current value read at call time (tests that set the env var
// per-case, or any future runtime-config override) — subscribeToPush()
// would keep using whatever was present the moment the module first
// loaded. Reading it inside a function each call fixes both without any
// behavior change in production.
function getVapidPublicKey(): string {
  return process.env.NEXT_PUBLIC_VAPID_PUBLIC_KEY ?? '';
}

export type SwUpdateListener = (registration: ServiceWorkerRegistration) => void;

let waitingUpdateListeners: SwUpdateListener[] = [];

/** يُسجَّل من AppProviders مرة واحدة عند إقلاع التطبيق. */
export async function registerServiceWorker(): Promise<ServiceWorkerRegistration | null> {
  if (typeof window === 'undefined') return null;
  if (!('serviceWorker' in navigator)) return null;
  // لا تسجيل في وضع التطوير لتفادي تعارضات HMR مع الكاش — القيمة
  // NEXT_PUBLIC_ENABLE_SW_DEV تسمح باختبار الـ SW يدويًا عند الحاجة.
  if (process.env.NODE_ENV === 'development' && process.env.NEXT_PUBLIC_ENABLE_SW_DEV !== 'true') {
    // FIX PWA-DEV-01: this guard is correct (avoids HMR/SW cache conflicts)
    // but was previously silent — testing offline/PWA behavior under
    // `next dev` looked broken with zero explanation. Log once so it's
    // discoverable without reading source.
    console.info(
      '[PWA] Service Worker skipped in development. Set NEXT_PUBLIC_ENABLE_SW_DEV=true in .env.local to test offline/PWA behavior locally.',
    );
    return null;
  }

  try {
    const registration = await navigator.serviceWorker.register('/sw.js', { scope: '/' });

    // نسخة جديدة تنتظر التفعيل (مستخدم فتح التطبيق أثناء وجود تحديث).
    if (registration.waiting) {
      waitingUpdateListeners.forEach((cb) => cb(registration));
    }

    registration.addEventListener('updatefound', () => {
      const newWorker = registration.installing;
      if (!newWorker) return;
      newWorker.addEventListener('statechange', () => {
        if (newWorker.state === 'installed' && navigator.serviceWorker.controller) {
          waitingUpdateListeners.forEach((cb) => cb(registration));
        }
      });
    });

    // عندما يتولى الـ SW الجديد السيطرة (بعد skipWaiting)، أعِد تحميل الصفحة
    // مرة واحدة فقط حتى لا يعمل المستخدم بخليط من كود قديم/جديد.
    let refreshing = false;
    navigator.serviceWorker.addEventListener('controllerchange', () => {
      if (refreshing) return;
      refreshing = true;
      window.location.reload();
    });

    // فحص دوري لوجود تحديث (كل ساعة) — يضمن ظهور زر التحديث حتى لو
    // فُتح التطبيق قبل نشر النسخة الجديدة.
    const UPDATE_CHECK_MS = 60 * 60 * 1000;
    const checkUpdate = () => {
      void registration.update().catch(() => undefined);
    };
    window.setInterval(checkUpdate, UPDATE_CHECK_MS);
    // فحص إضافي عند عودة التبويب
    const onVisible = () => {
      if (document.visibilityState === 'visible') checkUpdate();
    };
    document.addEventListener('visibilitychange', onVisible);
    // تنظيف عند إلغاء التسجيل نادرًا ما يحدث؛ نتركه بسيطًا.

    return registration;
  } catch (err) {
    // فشل التسجيل لا يجب أن يكسر التطبيق — PWA هي تحسين إضافي (progressive enhancement).
    console.warn('تعذّر تسجيل Service Worker:', err);
    return null;
  }
}

/** يُستدعى من مكوّن UpdatePrompt ليُبلَّغ عند توفر نسخة جديدة. */
export function onServiceWorkerUpdate(listener: SwUpdateListener): () => void {
  waitingUpdateListeners.push(listener);
  return () => {
    waitingUpdateListeners = waitingUpdateListeners.filter((l) => l !== listener);
  };
}

/**
 * يطلب من الـ SW الجديد (الموجود في حالة "waiting") تولي السيطرة فورًا.
 *
 * FIX PWA-UPDATE-01: كانت `registration.waiting?.postMessage(...)` — لو
 * كان `waiting` قد أصبح null بحلول لحظة الضغط (مثلًا: نافذة/تبويب آخر لنفس
 * التطبيق فعّل نفس التحديث أولًا، فتحوّل الـ SW من waiting إلى active قبل
 * أن يضغط المستخدم هنا)، فإن الـ postMessage يُطوى بصمت بفضل `?.` — لا
 * خطأ، لا رد فعل، لا تحديث. هذا يطابق تمامًا الأعراض المُبلَّغ عنها: ضغطة
 * الزر تُسجَّل بصريًا لكن لا شيء يتحمّل بعدها فعليًا.
 * أيضًا: حتى مع وجود waiting فعليًا، لو تأخّر حدث controllerchange لأي سبب
 * (بما فيها قيود دورة حياة SW المعروفة على iOS Safari للتطبيقات المثبتة
 * على الشاشة الرئيسية)، كان المستخدم يبقى عالقًا على الشاشة القديمة دون
 * أي مسار احتياطي.
 * الإصلاح: لو لا يوجد waiting، أعد التحميل مباشرة (التحديث غالبًا مُفعَّل
 * فعليًا). ولو يوجد، أرسل الرسالة كالمعتاد مع مؤقت احتياطي (3 ثوانٍ) يفرض
 * إعادة التحميل يدويًا إن لم ينطلق controllerchange بحلول ذلك الوقت.
 */
export type UpdateStage = 'activating' | 'reloading';

/**
 * onStage اختياري: يُستخدم من صفحة /update لعرض تقدّم التحديث للمستخدم
 * (انظر app/update/page.tsx). لا يغيّر أي سلوك فعلي — مجرد نداءات إضافية
 * عند كل مرحلة حقيقية من العملية الموجودة أصلًا.
 */
export function activateWaitingServiceWorker(
  registration: ServiceWorkerRegistration,
  onStage?: (stage: UpdateStage) => void,
): void {
  if (!registration.waiting) {
    onStage?.('reloading');
    window.location.reload();
    return;
  }
  onStage?.('activating');
  registration.waiting.postMessage({ type: 'SKIP_WAITING' });
  // إعادة التحميل الفعلية تحدث إما فورًا عبر controllerchange (مسجَّل في
  // registerServiceWorker أعلاه) أو عبر المهلة الاحتياطية بعد 3 ثوانٍ إن
  // لم ينطلق ذلك الحدث. نُبلّغ بمرحلة "إعادة التحميل" بعد فاصل قصير حتى لا
  // تُعرض للمستخدم كخطوتين متزامنتين.
  window.setTimeout(() => onStage?.('reloading'), 300);
  window.setTimeout(() => {
    window.location.reload();
  }, 3000);
}

// ── Push Notifications ──────────────────────────────────────────

function urlBase64ToUint8Array(base64String: string): BufferSource {
  const padding = '='.repeat((4 - (base64String.length % 4)) % 4);
  const base64 = (base64String + padding).replace(/-/g, '+').replace(/_/g, '/');
  const rawData = window.atob(base64);
  const outputArray = new Uint8Array(rawData.length);
  for (let i = 0; i < rawData.length; i++) {
    outputArray[i] = rawData.charCodeAt(i);
  }
  // FIX TS-PWA-01: newer TypeScript DOM lib versions type Uint8Array as
  // generic (Uint8Array<ArrayBufferLike>), which no longer structurally
  // satisfies PushManager.subscribe()'s stricter BufferSource parameter
  // in every TS/lib.dom combination. The runtime value is a completely
  // normal Uint8Array backed by a real ArrayBuffer — only the compile-time
  // type is overly narrow — so a direct return-type widening here is a
  // safe, targeted fix rather than a functional change.
  return outputArray as BufferSource;
}

export function isPushSupported(): boolean {
  return (
    typeof window !== 'undefined' && 'serviceWorker' in navigator && 'PushManager' in window
  );
}

export async function getPushSubscriptionState(): Promise<'subscribed' | 'unsubscribed' | 'unsupported'> {
  if (!isPushSupported()) return 'unsupported';
  const registration = await navigator.serviceWorker.ready;
  const subscription = await registration.pushManager.getSubscription();
  return subscription ? 'subscribed' : 'unsubscribed';
}

/**
 * يطلب إذن الإشعارات، ينشئ اشتراك Push، ويرسله للباك-إند لحفظه.
 *
 * ⚠️ يتطلب من الباك-إند إضافة نقطة `POST /notifications/push-subscriptions`
 * (غير موجودة حاليًا في src/modules — راجع قسم "المشاكل/المتطلبات
 * المتبقية" في التسليم) تستقبل { endpoint, keys: { p256dh, auth } }
 * وتربطها بالمستخدم الحالي عبر الـ Bearer token، بالإضافة لمتغير بيئة
 * NEXT_PUBLIC_VAPID_PUBLIC_KEY يجب توليده وضبطه في كلا الطرفين.
 */
export async function subscribeToPush(): Promise<boolean> {
  if (!isPushSupported()) return false;
  const vapidPublicKey = getVapidPublicKey();
  if (!vapidPublicKey) {
    console.warn('NEXT_PUBLIC_VAPID_PUBLIC_KEY غير مضبوط — لا يمكن تفعيل الإشعارات.');
    return false;
  }

  const permission = await Notification.requestPermission();
  if (permission !== 'granted') return false;

  const registration = await navigator.serviceWorker.ready;
  const subscription = await registration.pushManager.subscribe({
    userVisibleOnly: true,
    applicationServerKey: urlBase64ToUint8Array(vapidPublicKey),
  });

  try {
    await apiClient.post('/notifications/push-subscriptions', subscription.toJSON());
    return true;
  } catch (err) {
    // FIX PWA-CRITICAL-04: لو فشل حفظ الاشتراك في الباك-إند (مثلًا نقطة
    // /notifications/push-subscriptions غير منشورة بعد، أو خطأ شبكة)،
    // يبقى المتصفح مشتركًا فعليًا عبر pushManager دون أن يعرف الخادم
    // بذلك — تناقض حالة يجعل واجهة المستخدم تظهر "غير مفعّل" بينما
    // المتصفح يحمل اشتراكًا حيًا لن يُستخدم أبدًا ولن يمكن استبداله
    // بسهولة لاحقًا. نتراجع عن الاشتراك محليًا فورًا لإبقاء الحالتين متطابقتين.
    await subscription.unsubscribe().catch(() => undefined);
    throw err;
  }
}

export async function unsubscribeFromPush(): Promise<void> {
  if (!isPushSupported()) return;
  const registration = await navigator.serviceWorker.ready;
  const subscription = await registration.pushManager.getSubscription();
  if (!subscription) return;

  const endpoint = subscription.endpoint;
  await subscription.unsubscribe();
  await apiClient
    .delete('/notifications/push-subscriptions', { data: { endpoint } })
    .catch(() => undefined); // فشل حذف السجل من الخادم لا يجب أن يمنع الإلغاء المحلي
}

/**
 * AuthHydrationProvider
 *
 * Responsibilities:
 *  1. Wait for Zustand persist to rehydrate from localStorage before rendering.
 *  2. After hydration, ALWAYS call /auth/refresh — see PROD-FIX-15 note
 *     below for why this changed from "only if refreshToken exists".
 *  3. Fetch /users/me to populate avatarUrl/city missing from the login response.
 *
 * FIX AUTH-03 + C-04: Sets cookies for Next.js middleware:
 *   - app_access_token  (new access token, expires in 14 min to stay ahead of 15 min TTL)
 *   - app_user_role     (user.role for admin route protection)
 *   - app_has_session   (AUDIT-FIX C-1 — ~7 day hint mirroring the
 *                        backend's own copy; lets middleware avoid a
 *                        false /login redirect on a fresh page load
 *                        where app_access_token has already expired
 *                        but the httpOnly refreshToken is still valid)
 *
 * FIX T-09: setHydrated is only called once (from onRehydrateStorage callback
 *           in auth.store.ts). The useEffect here handles the async refresh flow.
 *
 * FIX PERF-01: Public pages no longer blocked — spinner only shown on
 *              protected/admin routes (handled by their layouts). This provider
 *              renders children immediately; route-level skeletons handle loading.
 *
 * AUDIT-FIX M-1: After a successful /me fetch, eagerly prefetch page 1 of
 *   /favorites so queryKeys.favorites.ids() is populated before the user
 *   ever visits /dashboard or /favorites. Previously useFavorites() (the
 *   only thing that populates the ids Set) was called from just those two
 *   pages, so a user who logged in and went straight to search saw every
 *   heart icon as "not saved" even for ads they'd actually favorited,
 *   until they happened to visit one of those two pages once in the
 *   session. Same prefetch pattern already used here for the user's own
 *   profile — just extended to favorites.
 *
 * PROD-FIX-15: refreshToken moved from localStorage into an httpOnly
 * cookie the backend sets directly (see backend-v9's
 * shared/utils/authCookies.ts) — this component can no longer read it
 * to decide "is there a session worth restoring" the way it used to
 * (`if (!refreshToken) { skip }`). The httpOnly cookie is, by design,
 * invisible to this code; the only way to find out whether a session
 * exists is to actually ask the backend. So this now ALWAYS attempts
 * /auth/refresh on mount:
 *   - If a valid refreshToken cookie exists, the browser sends it
 *     automatically (apiClient's withCredentials:true — see
 *     client.ts) and refresh succeeds, exactly as before.
 *   - If no cookie exists (a genuinely logged-out visitor), the
 *     backend's authController.refresh returns 401 (no refresh token
 *     provided) almost immediately — cheap, and functionally
 *     identical to the old "skip entirely" path from the user's
 *     perspective (falls into the catch block below, calls logout(),
 *     same end state as never having attempted it).
 * The one real behavior change: every page load now makes one extra
 * network round-trip for a logged-out visitor (previously zero, since
 * the old code could tell client-side there was nothing to refresh).
 * That's the unavoidable cost of the token no longer being readable
 * client-side at all — accepted deliberately as the trade for closing
 * the XSS exposure a JS-readable 7-day token represented.
 */
'use client';

import { useEffect, useRef } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { useAuthStore, selectIsHydrated } from '@/store/auth.store';
import { authApi }    from '@/api/auth.api';
import { usersApi }   from '@/api/users.api';
import { favoritesApi } from '@/api/favorites.api';
import { queryKeys }    from '@/lib/queryKeys';
import { setCookie, deleteCookie, cookieMaxAgeFromExpiresIn, SESSION_HINT_COOKIE_MAX_AGE } from '@/lib/cookies';

/**
 * FIX AUTH-OFFLINE-01: true only when the rejection actually carries an
 * HTTP response — i.e. the backend genuinely answered (401, 500,
 * whatever). false for a pure network failure (device offline, DNS/
 * timeout, or this component's own AbortController firing) — axios
 * always produces a `.response` of `undefined` in that case, never a
 * thrown value with no `.response` property at all.
 *
 * Deliberately NOT using lib/errorParser.ts's parseApiError here: it
 * gates its "real HTTP status" branch on axios.isAxiosError(), which
 * checks the internal `isAxiosError: true` marker axios stamps onto
 * its own error instances — a marker that (correctly) isn't present on
 * a hand-built `{ response: { status: 401 } }` test double, so
 * parseApiError would misclassify every such mock as "network failure"
 * too. This check only cares whether *some* `.response` is present,
 * which matches both a real AxiosError's shape and how this file's own
 * tests already model a genuine server rejection.
 */
function hasServerResponse(err: unknown): boolean {
  return !!(err && typeof err === 'object' && 'response' in err && (err as { response?: unknown }).response != null);
}

// FIX BUG-06: was a fixed re-export of AUTH_COOKIE_MAX_AGE — the
// refresh response's own tokens.expiresIn (captured below, right
// before this constant would previously have been used) now drives
// the actual maxAge via cookieMaxAgeFromExpiresIn instead.

interface AuthHydrationProviderProps {
  children: React.ReactNode;
}

export function AuthHydrationProvider({ children }: AuthHydrationProviderProps) {
  const isHydrated = useAuthStore(selectIsHydrated);
  const { setAccessToken, setCsrfToken, setUser, logout, setAuthResolved } = useAuthStore.getState();
  const queryClient = useQueryClient();

  const hasRunRef = useRef(false);

  useEffect(() => {
    // Only run once after Zustand has rehydrated from localStorage.
    if (!isHydrated || hasRunRef.current) return;
    hasRunRef.current = true;

    // API-INT-05 FIX: Wrap the entire auth-restore flow in a timeout.
    // Without this, a dead network (no response at all) causes the app to
    // hang in a semi-hydrated state indefinitely — isAuthenticated stays
    // false (since setAccessToken was never called) but no error is surfaced.
    // 8 seconds is generous: refresh + /me combined.
    //
    // FIX AUTH-05: previously the AbortController's signal was created
    // but never passed into authApi.refresh()/usersApi.getMe(), so
    // controller.abort() after 8s did nothing — the real bound was each
    // axios call's own 15s timeout (up to 30s for both, sequentially).
    // Now the signal is threaded through both calls so the 8s timeout
    // documented here is the one that actually applies.
    //
    // Declared here (not inside the IIFE below) so the effect's own
    // cleanup function — which aborts on unmount — can reach the same
    // controller instance; it previously lived inside the IIFE and was
    // out of scope for that cleanup, causing a ReferenceError.
    const controller = new AbortController();
    const timeout    = setTimeout(() => controller.abort(), 8_000);

    (async () => {
      try {
        // 1. Get a fresh access token. PROD-FIX-15: no refreshToken
        // argument anymore — the httpOnly cookie (if any) rides along
        // automatically via apiClient's withCredentials:true.
        const refreshRes = await authApi.refresh({ signal: controller.signal });
        const { accessToken: newAccess, expiresIn } = refreshRes.data.data!.tokens;

        setAccessToken(newAccess);
        // CROSS-ORIGIN-CSRF-FIX: this is the exact call that was
        // failing with 403 on every page reload — frontend and backend
        // are on different origins, so document.cookie can never see
        // the backend-origin-only csrfToken cookie (see lib/csrf.ts's
        // header comment for the full mechanism). Capture the value
        // from this response body instead, into the in-memory store
        // getCsrfToken() now reads from first.
        setCsrfToken(refreshRes.data.data!.csrfToken);

        // 2. Set middleware cookies so route protection works.
        // FIX BUG-06: derives maxAge from this response's own
        // tokens.expiresIn instead of the old fixed constant — reused
        // below for app_user_role too, since both cookies represent
        // the same access-token-backed session and should expire
        // together.
        const cookieMaxAge = cookieMaxAgeFromExpiresIn(expiresIn);
        setCookie('app_access_token', newAccess, cookieMaxAge);
        // AUDIT-FIX C-1: re-assert the session hint too (the backend
        // already set/refreshed its own copy via Set-Cookie on this
        // same /auth/refresh response — this client-side mirror just
        // means middleware doesn't have to wait on cookie propagation
        // timing before its very next request sees it).
        setCookie('app_has_session', '1', SESSION_HINT_COOKIE_MAX_AGE);

        // 3. Fetch full profile to get avatarUrl, city, and confirm role.
        const meRes  = await usersApi.getMe({ signal: controller.signal });
        const user   = meRes.data.data;
        if (!user) throw new Error('empty /users/me response');
        setUser({
          id:        user.id,
          name:      user.name,
          email:     user.email,
          role:      user.role as 'USER' | 'ADMIN',
          avatarUrl: user.avatarUrl,
          city:      user.city,
        });
        // Set role cookie for middleware admin check.
        setCookie('app_user_role', user.role, cookieMaxAge);

        // AUDIT-FIX M-1: prefetch page 1 of favorites so the ids Set is
        // populated app-wide before the user visits /dashboard or
        // /favorites. Best-effort — a failure here shouldn't sign the
        // user out or block the rest of hydration, so it's isolated in
        // its own try/catch and awaited (not fire-and-forget) only to
        // keep it inside this function's existing 8s abort window.
        try {
          // FIX AUTH-05b: pass the same signal used for refresh/getMe so
          // this call is actually cancelled by the 8s timeout or an
          // unmount, instead of running to completion in the background
          // regardless (see favoritesApi.getAll's doc comment).
          const favRes = await favoritesApi.getAll({ page: 1 }, { signal: controller.signal });
          const favData = favRes.data.data; // { items: FavoriteRecord[]; meta: PaginationMeta }
          if (!favData) throw new Error('empty /favorites response');
          const idSet   = new Set(favData.items.map((fav) => fav.ad.id));
          // Only seed the ids Set (the actual source of useIsFavorited()).
          // Deliberately NOT seeding queryKeys.favorites.all(...) here:
          // FavoritesList/DashboardStats call useFavorites() with different
          // params ({ page } vs none), producing different cache keys than
          // whatever this prefetch would use — seeding the wrong key would
          // just be dead cache, not a correctness issue, but there's no
          // reason to carry it.
          queryClient.setQueryData(queryKeys.favorites.ids(), idSet);
        } catch {
          // Non-fatal: heart icons just fall back to the old
          // "populate on first visit to /dashboard or /favorites"
          // behavior for this session.
        }

      } catch (err) {
        // FIX AUTH-OFFLINE-01: this used to call logout() unconditionally
        // on ANY failure here — including a bare network error (device
        // offline, DNS down, server unreachable), which is NOT the same
        // thing as the backend confirming "this session is invalid."
        // hasServerResponse() (defined above) is true only when the
        // backend actually answered (401, 500, whatever); a pure network
        // failure never carries a `.response`.
        //
        // Before this fix: disconnecting the internet and then loading
        // (or reloading) the app — which is exactly when this effect
        // runs, since it always fires once on mount per PROD-FIX-15 above
        // — looked identical to a truly expired session. logout() wiped
        // the persisted `user` (so even the header/avatar vanished) and
        // deleted app_access_token/app_user_role/app_has_session, then
        // ProtectedLayout (isAuthenticated now false) redirected straight
        // to /login. That redirect is also *why* offline-cached content
        // (conversations, notifications — anything behind that layout)
        // never had a chance to render: the user was bounced away from
        // the page before ever reaching the cached shell/data this app
        // otherwise keeps for exactly this situation.
        //
        // Fix: on a network failure specifically, don't touch anything —
        // leave the persisted `user` and session cookies exactly as they
        // were. isAuthenticated stays false (it was never proven true
        // this load either way), but ProtectedLayout now treats "offline
        // + a persisted user" as reason enough to render its cached
        // children instead of redirecting (see that file). The very next
        // successful refresh (automatic retry, or simply coming back
        // online and reloading) resolves this for real in either
        // direction — confirms the session and flips isAuthenticated
        // true, or genuinely rejects it and logs out then, once that's
        // an actual answer from the server instead of a guess.
        if (hasServerResponse(err)) {
          logout();
          deleteCookie('app_access_token');
          deleteCookie('app_user_role');
          deleteCookie('app_has_session'); // AUDIT-FIX C-1
        }
      } finally {
        clearTimeout(timeout);
        // FIX AUTH-04: always mark the restore flow as settled, success
        // or failure, so ProtectedLayout/AdminLayout stop waiting.
        setAuthResolved();
      }
    })();

    // Abort any in-flight refresh/me/favorites calls if this component
    // unmounts before the flow settles (e.g. the user navigates away,
    // or — in tests — the next test renders a new instance without a
    // previous one having finished). Without this, the async IIFE above
    // keeps running after unmount and can still call store setters.
    return () => controller.abort();
  }, [isHydrated]);

  // FIX PERF-01: No blocking spinner here — render children immediately.
  // Protected/admin layouts show their own skeleton while auth resolves.
  return <>{children}</>;
}

/**
 * Service Worker — سوق غزة PWA
 *
 * استراتيجيات التخزين المؤقت:
 *  - App Shell (HTML/CSS/JS الأساسية): Stale-While-Revalidate
 *  - الصور (Cloudinary + الأيقونات المحلية): Cache First مع حد أقصى للعمر
 *  - طلبات API (GET): Network First مع fallback على الكاش عند انقطاع الشبكة
 *  - طلبات API (POST/PUT/PATCH/DELETE) الفاشلة بسبب انقطاع الشبكة: تُحفظ في
 *    IndexedDB Queue وتُعاد تلقائيًا عند عودة الاتصال (Background Sync)
 *  - لا كاش إطلاقًا لطلبات auth (/auth/*) لتفادي تسريب أو تقديم بيانات جلسة قديمة
 *
 * الإصدار أدناه (CACHE_VERSION) يجب رفعه يدويًا مع كل تغيير في استراتيجية
 * الكاش أو أصول الـ App Shell — هذا ما يضمن تحديث المستخدمين تلقائيًا وعدم
 * بقائهم على نسخة قديمة من التطبيق (bug شائع في PWAs المبنية بسرعة).
 *
 * ملاحظة استعادة: هذا الملف كان مبتورًا (فقط الترويسة + ثوابت أسماء الكاش)
 * — أعيد بناؤه بالكامل بالاعتماد على العقود الموثّقة صراحة في lib/pwa.ts،
 * lib/offlineQueue.ts، lib/offlineCoreBundle.ts، lib/offlineRouteShells.ts،
 * backend/.../pushService.ts، و__tests__/unit/lib/sw.test.ts (المصدر الوحيد
 * القابل للتحقق آليًا من بين كل هذه المراجع). isProtectedPage/isNeverCache/
 * isApiRequest ومستمع CLEAR_API_CACHE مطابقة لذلك الاختبار حرفيًا. باقي
 * المنطق (fetch strategies, IndexedDB queue, background sync, push) غير
 * مُغطى باختبارات — مبني على التعليقات المرجعية بأمانة قدر الإمكان لكنه لم
 * يُشغَّل فعليًا بمتصفح حقيقي في هذه الجلسة (لا شبكة/build متاح هنا).
 */

// FIX PWA-VER-01: كان CACHE_VERSION هنا 'v5' بينما lib/offlineRouteShells.ts
// وlib/offlineCoreBundle.ts (اللذان يفترض أن يطابقا هذه القيمة "حرفيًا" حسب
// تعليقاتهما الخاصة) كانا لا يزالان مثبَّتين على 'v4' — عدم تطابق حقيقي كان
// يعني: (1) warmRouteShells() تكتب شِلال الصفحات العامة المُسخَّنة مسبقًا
// (/, /products, /stores...) في كاش 'market-static-v4' الذي لا يقرأ منه
// معالج fetch هنا أبدًا (يقرأ من STATIC_CACHE = market-static-v5)، و(2)
// 'activate' أدناه يحذف أي كاش يبدأ بـ market- وليس ضمن currentCaches —
// فكاش v4 كان يُمسح فورًا بعد كل تفعيل SW جديد. نفس المشكلة بالضبط
// لـ CORE_CACHE (PHASE-1 Offline Core Bundle). النتيجة العملية: ميزتا
// "تصفّح المسارات العامة بدون نت" و"الحزمة الأساسية بدون نت" كانتا معطَّلتين
// فعليًا رغم وجود الكود بالكامل. رُفع CACHE_VERSION هنا إلى 'v6' وطُبِّق نفس
// الرقم بالملفين الآخرين لإعادة المزامنة (انظر تعليقيهما).
const CACHE_VERSION = 'v6';
const STATIC_CACHE = `market-static-${CACHE_VERSION}`;
const IMAGE_CACHE = `market-images-${CACHE_VERSION}`;
const API_CACHE = `market-api-${CACHE_VERSION}`;
// FEAT-OFFLINE-MSG (وسِّع لاحقًا ليشمل /notifications، انظر
// isPersonalShellRoute أدناه): كاش شكل الصفحة (page shell) لمسارات محمية
// "شخصية لكن بلا محتوى مُخصَّص فعليًا بالـ HTML/RSC" تحديدًا — بقية الصفحات
// المحمية (isProtectedPage) تبقى "شبكة فقط" كما كانت (audit #7: محتوى شخصي،
// لا يجوز تخزينه بجانب STATIC_CACHE العام). هذا الكاش مسموح استثناءً لأنه
// يُعامَل بنفس الحماية اللي API_CACHE أصلاً يُعامَل بها (وAPI_CACHE فعليًا
// يخزّن نفس درجة الحساسية — بيانات الرسائل/الإشعارات نفسها) — يُمسح بالكامل
// عند تسجيل الخروج (CLEAR_API_CACHE أدناه) بدل تركه محفوظًا لمستخدم تالٍ
// على جهاز مشترك.
const PERSONAL_SHELL_CACHE = `market-personal-shell-${CACHE_VERSION}`;
// PHASE-1 (Offline Core Bundle): كاش منفصل عن API_CACHE عمدًا. API_CACHE
// محدود بـ MAX_API_ENTRIES=60 ويُقلَّم بترتيب FIFO تقريبي (انظر trimCache) —
// أي تصفح عادي بعد warm-up كافٍ لإخراج طلبات الحزمة الأساسية (تصنيفات/
// منتجات مميزة/متاجر) من الكاش قبل ما يحتاجها المستخدم فعليًا بدون نت.
// CORE_CACHE لا يُقلَّم أبدًا تلقائيًا — يُحدَّث فقط عبر warmCoreBundle()
// (lib/offlineCoreBundle.ts) صراحة، فيبقى ثابت المحتوى بين مرات التصفح.
const CORE_CACHE = `market-core-${CACHE_VERSION}`; // يجب مطابقة lib/offlineCoreBundle.ts's CORE_CACHE حرفيًا

// PHASE-OFFLINE-AD-DETAIL: كاش "الإعلانات المحفوظة يدويًا للعمل بدون
// اتصال" (زر بـ AdDetail.tsx، يديره lib/offlineSavedAds.ts). بدون رقم
// إصدار عمدًا — خلافًا لبقية الكاشات أعلاه، هذا اختيار صريح من المستخدم
// ولا يجب أن يُمسح تلقائيًا مع كل ترقية CACHE_VERSION عادية. يجب مطابقة
// lib/offlineSavedAds.ts's SAVED_ADS_CACHE حرفيًا، ويجب إضافته لقائمة
// currentCaches بـ 'activate' أدناه وإلا سيُحذف كأي كاش market-* غير معروف.
const SAVED_ADS_CACHE = 'market-saved-ads';

const MAX_API_ENTRIES = 60;
const OFFLINE_URL = '/offline';

// يجب مطابقة lib/offlineQueue.ts حرفيًا — الصفحة تقرأ من نفس القاعدة/المخزن.
const QUEUE_DB_NAME = 'market-offline-queue';
const QUEUE_DB_VERSION = 1;
const QUEUE_STORE_NAME = 'requests';

const SYNC_TAG = 'replay-offline-queue';

// ── تصنيف الطلبات ───────────────────────────────────────────────

/**
 * صفحات محمية/شخصية — لا تُقرأ ولا تُكتب أبدًا في STATIC_CACHE (audit #7):
 * محتواها خاص بالمستخدم، وتخزينه يخاطر بعرضه لمستخدم آخر على نفس الجهاز.
 */
function isProtectedPage(url) {
  const protectedPrefixes = [
    '/dashboard',
    '/settings',
    '/my-ads',
    '/my-services',
    '/favorites',
    '/messages',
    // FIX PWA-NOTIF-01: كانت /notifications غائبة عن هذه القائمة رغم كونها
    // صفحة محمية شخصية بالكامل (تحت (protected) وتتطلب تسجيل دخول) — يعني
    // كانت تمر من handlePageRequest كصفحة "عامة" وتُخزَّن شكلها في
    // STATIC_CACHE العام (لا يُمسح عند تسجيل الخروج)، خلافًا لسياسة audit #7
    // الموثّقة أعلاه لبقية هذه القائمة بالضبط. لم يكن هذا يسرّب بيانات فعلية
    // (الصفحة 'use client' بالكامل ومحتوى الإشعارات يُجلب عبر React Query،
    // لا يُخبَز داخل HTML/RSC المخزَّن) لكنه تصنيف غير متسق وغير آمن
    // بالتصميم لأي تغيير مستقبلي بالصفحة. أُضيفت هنا والآن تُعامَل كصفحة
    // محمية بشِل مخزَّن آمن (انظر isPersonalShellRoute) بدل الاعتماد
    // بالصدفة على السلوك العام.
    '/notifications',
    '/ads/create',
    '/admin',
  ];
  return protectedPrefixes.some(
    (prefix) => url.pathname === prefix || url.pathname.startsWith(`${prefix}/`),
  );
}

/** لا كاش إطلاقًا — مصادقة/CSRF. تسريب استجابة قديمة هنا أخطر من أي فائدة أوفلاين. */
function isNeverCache(url) {
  return url.pathname.includes('/auth/') || url.pathname.includes('/csrf');
}

function isApiRequest(url) {
  return url.pathname.includes('/api/');
}

/** الصور: destination='image' يغطي عناصر <img>، وفحص المضيف يغطي الجلب
 * البرمجي المباشر (fetch(url) من warmCoreBundle للصور المصغّرة) اللي لا
 * يحمل destination='image' لأنه ليس طلب موارد فرعي حقيقي من HTML. */
function isImageRequest(request, url) {
  if (request.destination === 'image') return true;
  return url.hostname.includes('cloudinary.com');
}

/** طلب RSC (تنقّل SPA ناعم) — Next.js App Router يرسله برأس RSC:'1' بدل
 * navigate كامل. انظر PHASE-3-B في lib/offlineRouteShells.ts للتفصيل. */
function isRscShellRequest(request) {
  return request.headers.get('RSC') === '1';
}

/** يجب مطابقة lib/offlineRouteShells.ts's rscShellKey() حرفيًا. */
function rscShellKey(pathname) {
  return `${pathname}?__offline_rsc_shell`;
}

/** FEAT-OFFLINE-MSG + FIX PWA-NOTIF-01: نطاق محدود عمدًا — /messages،
 * /messages/:id، و/notifications فقط، وليس كل isProtectedPage. هذه هي
 * المسارات المحمية الوحيدة التي رُوجعت وتحقّقنا أنها آمنة لتخزين شكلها
 * (لا بيانات مستخدم مخبوزة داخل HTML/RSC نفسه — كلتاهما 'use client' بالكامل
 * وتجلبان بياناتهما عبر React Query بعد الـ hydration). توسيعه لبقية
 * الصفحات المحمية (dashboard/settings/admin...) قرار منفصل يستأهل مراجعة
 * حساسية بيانات خاصة به لكل صفحة على حدة. */
function isPersonalShellRoute(url) {
  return (
    url.pathname === '/messages' ||
    url.pathname.startsWith('/messages/') ||
    url.pathname === '/notifications'
  );
}

// ── استراتيجيات التخزين ─────────────────────────────────────────

/** يحذف رأس Vary قبل التخزين — نفس منطق offlineRouteShells.ts's
 * stripVaryAndClone، لأن Cache API يرفض المطابقة لاحقًا لو بقي Vary حاضرًا
 * حتى مع تطابق مفتاح البحث تمامًا. */
async function stripVaryAndClone(response) {
  const headers = new Headers(response.headers);
  headers.delete('Vary');
  const body = await response.blob();
  return new Response(body, {
    status: response.status,
    statusText: response.statusText,
    headers,
  });
}

/** Stale-While-Revalidate عام — يُستخدم لصفحات App Shell العامة (navigate +
 * RSC shells) ولأصول JS/CSS الثابتة. يرجع النسخة المخزَّنة فورًا إن وُجدت
 * (سرعة + عمل أوفلاين)، ويحدّث الكاش بالخلفية دائمًا عبر event.waitUntil. */
async function staleWhileRevalidate(event, request, cacheKey) {
  const cache = await caches.open(STATIC_CACHE);
  const cachedResponse = await cache.match(cacheKey);

  const networkFetch = fetch(request)
    .then(async (response) => {
      if (response && response.ok) {
        const toStore = isRscShellRequest(request)
          ? await stripVaryAndClone(response.clone())
          : response.clone();
        await cache.put(cacheKey, toStore);
      }
      return response;
    })
    .catch(() => undefined);

  event.waitUntil(networkFetch);

  if (cachedResponse) return cachedResponse;

  const networkResponse = await networkFetch;
  if (networkResponse) return networkResponse;

  const offlineFallback = await cache.match(OFFLINE_URL);
  return offlineFallback || Response.error();
}

/** تنقّل/RSC لصفحة محمية: شبكة أولًا، بدون أي قراءة أو كتابة على STATIC_CACHE
 * العام (audit #7 — يبقى ساريًا لكل الصفحات المحمية الأخرى). عند فشل
 * الشبكة، أقصى ما نقدّمه لغالبية الصفحات المحمية هو /offline نفسها —
 * لا نسخة مخزَّنة من الصفحة المحمية (لا توجد أصلًا).
 *
 * FEAT-OFFLINE-MSG + FIX PWA-NOTIF-01: استثناء محدود لمسارات الرسائل
 * والإشعارات فقط (isPersonalShellRoute) — "قراءة المحادثات/الإشعارات
 * المحفوظة أوفلاين" يتطلب أن يصل المستخدم أصلًا لشكل الصفحة (/messages،
 * /messages/:id، أو /notifications) حتى تقدر بياناتها (المخزَّنة أصلاً
 * بـ API_CACHE عبر networkFirstApi لطلبات API، وبـ localStorage عبر
 * lib/notificationsCache.ts للإشعارات تحديدًا) تُعرض؛ بدون هذا، أي تنقّل
 * (حتى soft-nav RSC) وهو أوفلاين كان يفشل عند طلب شكل الصفحة نفسه ويعرض
 * /offline العامة بدل المحتوى المخزَّن فعليًا. مخزَّن بـ PERSONAL_SHELL_CACHE
 * (كاش منفصل، يُمسح كاملًا عند تسجيل الخروج تمامًا مثل API_CACHE — انظر
 * تعليق تعريفه أعلاه). */
async function handleProtectedPage(request, url) {
  const useShellCache = isPersonalShellRoute(url);
  const cacheKey = isRscShellRequest(request) ? rscShellKey(url.pathname) : request;

  try {
    const response = await fetch(request);
    if (useShellCache && response && response.ok) {
      const cache = await caches.open(PERSONAL_SHELL_CACHE);
      const toStore = isRscShellRequest(request)
        ? await stripVaryAndClone(response.clone())
        : response.clone();
      await cache.put(cacheKey, toStore);
    }
    return response;
  } catch {
    if (useShellCache) {
      const shellCache = await caches.open(PERSONAL_SHELL_CACHE);
      const cachedShell = await shellCache.match(cacheKey);
      if (cachedShell) return cachedShell;
    }
    const cache = await caches.open(STATIC_CACHE);
    const offlineFallback = await cache.match(OFFLINE_URL);
    return offlineFallback || Response.error();
  }
}

async function handlePageRequest(event, request, url) {
  if (isProtectedPage(url)) {
    return handleProtectedPage(request, url);
  }
  const cacheKey = isRscShellRequest(request) ? rscShellKey(url.pathname) : request;
  return staleWhileRevalidate(event, request, cacheKey);
}

/** Cache First للصور — تُخزَّن لأجل غير مسمى (لا تنتهي صلاحيتها تلقائيًا هنا؛
 * حجم كاش الصور محدود عمليًا بعدد الصور المعروضة فعليًا للمستخدم). */
async function cacheFirstImage(event, request, url) {
  const cache = await caches.open(IMAGE_CACHE);
  const cached = await cache.match(request);
  if (cached) return cached;

  // PHASE-OFFLINE-AD-DETAIL: صورة إعلان محفوظ يدويًا قد لا تكون مرّت
  // بعد بـ IMAGE_CACHE (مثلًا thumbnail بالأسفل بـ loading="lazy" لم
  // يُعرض فعليًا بعد) لكنها مخزَّنة صراحة بـ SAVED_ADS_CACHE عبر
  // lib/offlineSavedAds.ts's saveAdOffline — تحقّق منه قبل الشبكة.
  const savedCache = await caches.open(SAVED_ADS_CACHE);
  const savedHit = await savedCache.match(request);
  if (savedHit) return savedHit;

  // PHASE-OFFLINE-AD-DETAIL (fallback ثانٍ): Next.js Image Optimization
  // مفعّل (next.config.ts's images.remotePatterns)، فالطلب الفعلي اللي
  // المتصفح يرسله عبر <SafeImage>/next-image ليس رابط Cloudinary الخام
  // اللي saveAdOffline حفظه صراحة، بل /_next/image?url=<مُرمَّز>&w=...
  // بمقاس يختاره Next وقت العرض (يعتمد على حجم الشاشة/DPR — غير قابل
  // للتنبؤ به مسبقًا). فك ترميز ?url= هنا ومطابقته بالرابط الخام
  // المحفوظ يعطي أقله نسخة غير محسَّنة من نفس الصورة بدل فشل تحميل
  // كامل — تدهور مقبول لا صورة مكسورة تمامًا.
  if (url.pathname === '/_next/image') {
    const inner = url.searchParams.get('url');
    if (inner) {
      try {
        const rawHit = await savedCache.match(decodeURIComponent(inner));
        if (rawHit) return rawHit;
      } catch {
        // رابط ?url= مُرمَّز بشكل غير صالح — تجاهل والمتابعة للشبكة.
      }
    }
  }

  try {
    const response = await fetch(request);
    if (response && response.ok) {
      event.waitUntil(cache.put(request, response.clone()));
    }
    return response;
  } catch {
    return Response.error();
  }
}

/** يُبقي API_CACHE ضمن MAX_API_ENTRIES بترتيب FIFO تقريبي — cache.keys()
 * يرجع بترتيب الإدخال تقريبًا في المتصفحات الحالية، وهذا كافٍ هنا (ليس
 * ترتيبًا مضمونًا بالمواصفة لكنه سلوك عملي مقبول لتقليم غير حرج). */
async function trimCache(cacheName, maxEntries) {
  const cache = await caches.open(cacheName);
  const keys = await cache.keys();
  if (keys.length <= maxEntries) return;
  const excess = keys.length - maxEntries;
  for (let i = 0; i < excess; i += 1) {
    await cache.delete(keys[i]);
  }
}

/** Network First لطلبات API (GET) — عند فشل الشبكة: API_CACHE أولًا (آخر
 * استجابة فعلية زارها المستخدم)، ثم CORE_CACHE (الحزمة الأساسية المحمَّلة
 * استباقيًا عبر warmCoreBundle لمسارات لم تُزَر من قبل). */
async function networkFirstApi(event, request, url) {
  const cache = await caches.open(API_CACHE);
  try {
    const response = await fetch(request);
    if (response && response.ok) {
      event.waitUntil(
        cache.put(request, response.clone()).then(() => trimCache(API_CACHE, MAX_API_ENTRIES)),
      );
    }
    return response;
  } catch {
    const cachedApi = await cache.match(request);
    if (cachedApi) return cachedApi;

    const coreCache = await caches.open(CORE_CACHE);
    const cachedCore = await coreCache.match(request.url);
    if (cachedCore) return cachedCore;

    // PHASE-OFFLINE-AD-DETAIL: GET /ads/:id لإعلان محفوظ يدويًا — آخر
    // طبقة fallback، بعد API_CACHE (تصفح عادي حديث) وCORE_CACHE (حزمة
    // استباقية عامة). انظر تعليق lib/offlineSavedAds.ts للسياق الكامل.
    const savedCache = await caches.open(SAVED_ADS_CACHE);
    const cachedSaved = await savedCache.match(request.url);
    if (cachedSaved) return cachedSaved;

    return Response.error();
  }
}

// ── طابور الطلبات غير المتصلة (IndexedDB) ───────────────────────
// يجب أن يبقى DB_NAME/DB_VERSION/STORE_NAME مطابقًا تمامًا لـ lib/offlineQueue.ts.

function openQueueDb() {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open(QUEUE_DB_NAME, QUEUE_DB_VERSION);
    req.onupgradeneeded = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains(QUEUE_STORE_NAME)) {
        db.createObjectStore(QUEUE_STORE_NAME, { keyPath: 'id', autoIncrement: true });
      }
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

/** status افتراضيًا 'pending' — أُضيف صراحة مع FEAT-OFFLINE-MSG (كان
 * ضمنيًا/غير موجود سابقًا: كل عنصر بالطابور كان "معلّقًا" حتى يُحذف عند
 * نجاح أو فشل نهائي، بلا تمييز). لا يُكسر أي مستهلك قديم للطابور — عنصر
 * بلا status يُعامَل كـ pending أيضًا (انظر الفحص أدناه). */
async function queueRequestEntry(entry) {
  const db = await openQueueDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(QUEUE_STORE_NAME, 'readwrite');
    tx.objectStore(QUEUE_STORE_NAME).add({ status: 'pending', ...entry });
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

async function getAllQueuedEntries() {
  const db = await openQueueDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(QUEUE_STORE_NAME, 'readonly');
    const req = tx.objectStore(QUEUE_STORE_NAME).getAll();
    req.onsuccess = () => resolve(req.result || []);
    req.onerror = () => reject(req.error);
  });
}

async function getQueuedEntry(id) {
  const db = await openQueueDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(QUEUE_STORE_NAME, 'readonly');
    const req = tx.objectStore(QUEUE_STORE_NAME).get(id);
    req.onsuccess = () => resolve(req.result || null);
    req.onerror = () => reject(req.error);
  });
}

async function deleteQueuedEntry(id) {
  const db = await openQueueDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(QUEUE_STORE_NAME, 'readwrite');
    tx.objectStore(QUEUE_STORE_NAME).delete(id);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

/** FEAT-OFFLINE-MSG: يستبدل حذف العنصر بتحديثه (put بنفس الـ id — keyPath
 * صريح بالكائن، لا حاجة لتمريره منفصلًا) — يبقيه بالطابور بحالة 'failed'
 * بدل اختفائه بصمت، وهذا بالضبط ما يسمح لواجهة المحادثة بعرض "فشل
 * الإرسال" مع خيار إعادة المحاولة/الحذف بدل أن تُسقِط الرسالة بلا أثر. */
async function markQueuedEntry(id, patch) {
  const db = await openQueueDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(QUEUE_STORE_NAME, 'readwrite');
    const store = tx.objectStore(QUEUE_STORE_NAME);
    const getReq = store.get(id);
    getReq.onsuccess = () => {
      const current = getReq.result;
      if (!current) {
        resolve(null);
        return;
      }
      const updated = { ...current, ...patch };
      store.put(updated);
      tx.oncomplete = () => resolve(updated);
    };
    getReq.onerror = () => reject(getReq.error);
  });
}

async function notifyClients(message) {
  const clientsList = await self.clients.matchAll();
  clientsList.forEach((client) => client.postMessage(message));
}

/**
 * FIX CONFLICT-01 (كان جزءًا من replayQueue حرفيًا قبل هذا التعديل):
 * محاولة إرسال عنصر واحد من الطابور. الفرق عن السلوك القديم —
 * خطأ عميل نهائي (4xx، مثلًا 403 USER_BLOCKED لو حظر الطرف الآخر أثناء
 * الانقطاع، أو 404 لو حُذفت المحادثة) كان يُحذف من الطابور بصمت تمامًا
 * كنجاح — أي أن رسالة "فشلت" فعليًا تختفي بلا أي أثر للمستخدم، فيظن أنها
 * وصلت. الآن: 4xx يُبقي العنصر بالطابور بحالة 'failed' (مع تفاصيل الخطأ)
 * بدل حذفه، ويُخطر الواجهة بعنصر بعينه فشل — القرار (إعادة محاولة يدويًا/
 * حذف) يُترك للمستخدم بدل أن يُتخذ صامتًا نيابة عنه. 5xx/انقطاع فعلي يبقيان
 * كما كانا: العنصر يبقى pending ولا يُخطَر بفشل (قد ينجح لاحقًا بلا تدخل).
 * يُرجع 'sent' | 'failed' | 'still-offline' — يستخدمها replayQueue لمعرفة
 * متى تتوقف عن باقي الطابور (فقط عند 'still-offline').
 */
async function replayOne(entry) {
  try {
    const response = await fetch(entry.url, {
      method: entry.method,
      headers: entry.headers,
      body: entry.body ?? undefined,
      credentials: 'same-origin',
    });

    if (response.ok) {
      await deleteQueuedEntry(entry.id);
      await notifyClients({ type: 'QUEUE_ITEM_SENT', id: entry.id, url: entry.url });
      return 'sent';
    }

    if (response.status >= 400 && response.status < 500) {
      let message;
      try {
        const data = await response.clone().json();
        message = typeof data?.message === 'string' ? data.message : undefined;
      } catch {
        message = undefined;
      }
      await markQueuedEntry(entry.id, {
        status: 'failed',
        lastError: { status: response.status, message },
      });
      await notifyClients({
        type: 'QUEUE_ITEM_FAILED',
        id: entry.id,
        url: entry.url,
        status: response.status,
        message,
      });
      return 'failed';
    }

    // 5xx أو حالة غير متوقعة أخرى — مشكلة خادم مؤقتة على الأرجح، اترك
    // العنصر pending وأعد المحاولة لاحقًا بلا تغيير حالته.
    return 'still-offline';
  } catch {
    return 'still-offline';
  }
}

/** تُستدعى من حدث 'sync' (Background Sync) ومن رسالة REPLAY_QUEUE_NOW
 * (fallback يدوي للمتصفحات بلا Background Sync، خاصة iOS Safari — انظر
 * lib/offlineQueue.ts's requestQueueReplay). تُعيد المحاولة بترتيب الإدخال؛
 * تتخطى العناصر 'failed' (فشل نهائي مُعلَن — لا تُعاد تلقائيًا، فقط عبر
 * RETRY_QUEUE_ITEM الصريح)، وتتوقف عند أول عنصر لا يزال "أوفلاين فعليًا"
 * (still-offline) لتحافظ على الترتيب — لكنها لا تتوقف عند 4xx نهائي بعد
 * الآن (FIX CONFLICT-01)، فرسالة فشلت لسبب لا علاقة له بالاتصال لا يجب أن
 * تحجب باقي عناصر الطابور (لمحادثات/عمليات أخرى قد تنجح بلا مشكلة). */
async function replayQueue() {
  let entries;
  try {
    entries = await getAllQueuedEntries();
  } catch {
    return;
  }

  for (const entry of entries) {
    if (entry.status === 'failed') continue;
    const result = await replayOne(entry);
    if (result === 'still-offline') break;
  }

  await notifyClients({ type: 'QUEUE_REPLAYED' });
}

/** طلبات API غير GET (POST/PUT/PATCH/DELETE) — عند فشل الشبكة تُحفظ بالطابور
 * وتُرجَع استجابة 202 {queued:true} يتعرّف عليها api/client.ts's response
 * interceptor فيمنع أي onSuccess/toast نجاح كاذب لعملية لم تصل فعليًا. */
async function handleMutation(request) {
  const requestForQueue = request.clone();
  try {
    return await fetch(request);
  } catch {
    // FIX OFFLINE-ADS-01: كان الجسم يُقرأ عبر .text()، وهذا يفكّ ترميز
    // البايتات كـ UTF-8 قبل إعادة تخزينها — عملية غير عكسية لبيانات
    // ثنائية. طلبات إنشاء/تعديل الإعلانات (وأي رفع صور آخر) هي
    // multipart/form-data وتحمل بايتات صور خامة ضمن نفس الجسم النصي
    // ظاهريًا؛ .text() كان يُتلف تلك البايتات بصمت (كل بايت غير صالح
    // UTF-8 يُستبدل بحرف ), فيصل السيرفر لاحقًا صورة تالفة أو يفشل تحليل
    // multipart أصلاً — أي أن "طابور الأوفلاين" كان يبتلع الطلب بصمت وكأنه
    // نجح (202 queued) بينما هو فعليًا مفقود عمليًا عند إعادة الإرسال.
    // .blob() يحفظ البايتات كما هي تمامًا؛ IndexedDB يخزّن Blob مباشرة
    // (structured clone) و fetch() يقبله كـ body دون أي تحويل إضافي.
    let body = null;
    try {
      const blob = await requestForQueue.blob();
      body = blob.size > 0 ? blob : null;
    } catch {
      body = null;
    }
    const headers = {};
    requestForQueue.headers.forEach((value, key) => {
      headers[key] = value;
    });

    try {
      await queueRequestEntry({
        url: requestForQueue.url,
        method: requestForQueue.method,
        headers,
        body,
        queuedAt: Date.now(),
      });
    } catch {
      return Response.error();
    }

    if (self.registration && self.registration.sync) {
      try {
        await self.registration.sync.register(SYNC_TAG);
      } catch {
        // Background Sync غير مدعوم (iOS Safari مثلًا) — لا مشكلة، fallback
        // اليدوي عبر REPLAY_QUEUE_NOW (lib/offlineQueue.ts) يغطي هذه الحالة.
      }
    }

    return new Response(
      JSON.stringify({
        queued: true,
        message: 'لا يوجد اتصال — سيُعاد إرسال العملية تلقائيًا عند عودة الاتصال.',
      }),
      { status: 202, headers: { 'Content-Type': 'application/json' } },
    );
  }
}

// ── دورة حياة الـ Service Worker ────────────────────────────────

self.addEventListener('install', (event) => {
  // FIX OFFLINE-PRECACHE: بدون هذا، cache.match(OFFLINE_URL) بـ
  // staleWhileRevalidate/handleProtectedPage يفشل دائمًا حتى يزور المستخدم
  // /offline بنفسه وهو أونلاين ولو مرة — يعني أول انقطاع اتصال فعلي
  // (بالضبط اللحظة اللي الصفحة مصمَّمة لأجلها) يُظهر خطأ شبكة خام بدل
  // الصفحة المصمَّمة. لا self.skipWaiting() هنا رغم ذلك — التفعيل يبقى
  // بإذن المستخدم فقط، انظر التعليق أسفل.
  event.waitUntil(
    (async () => {
      try {
        const cache = await caches.open(STATIC_CACHE);
        await cache.add(OFFLINE_URL);
      } catch {
        // فشل التخزين المسبق (مثلًا لا اتصال أصلًا وقت التثبيت، حالة نادرة)
        // لا يجب أن يوقف تثبيت الـ SW — ستُخزَّن لاحقًا بأول زيارة عادية
        // لها إن حدثت.
      }
    })(),
  );
  // عمدًا: لا self.skipWaiting() هنا. التفعيل يتم فقط بإذن المستخدم عبر
  // رسالة SKIP_WAITING (زر "تحديث الآن" بـ UpdatePrompt.tsx) — لا نريد
  // تحديثًا قسريًا وإعادة تحميل مفاجئة أثناء تعبئة نموذج. انظر lib/pwa.ts
  // وتعليق UpdatePrompt.tsx للتفصيل الكامل.
});

self.addEventListener('activate', (event) => {
  const currentCaches = [
    STATIC_CACHE,
    IMAGE_CACHE,
    API_CACHE,
    CORE_CACHE,
    SAVED_ADS_CACHE,
    PERSONAL_SHELL_CACHE,
  ];
  event.waitUntil(
    (async () => {
      const cacheNames = await caches.keys();
      await Promise.all(
        cacheNames
          .filter((name) => name.startsWith('market-') && !currentCaches.includes(name))
          .map((name) => caches.delete(name)),
      );
      await self.clients.claim();
    })(),
  );
});

self.addEventListener('message', (event) => {
  const type = event.data && event.data.type;

  if (type === 'SKIP_WAITING') {
    self.skipWaiting();
    return;
  }

  if (type === 'CLEAR_API_CACHE') {
    // SECURITY FIX (audit #2): تُستدعى عند تسجيل الخروج (useAuthMutations.ts's
    // clearServiceWorkerApiCache) — تمنع تسريب استجابات API مخزَّنة لمستخدم
    // سابق على جهاز مشترك للمستخدم التالي الذي يسجّل دخوله.
    // FEAT-OFFLINE-MSG + FIX PWA-NOTIF-01: PERSONAL_SHELL_CACHE يحمل نفس
    // درجة الحساسية (شكل صفحة محادثة قد يتضمن أسماء/معاينة رسائل، أو شكل
    // صفحة إشعارات) — يُمسح هنا معه لنفس السبب.
    event.waitUntil(Promise.all([caches.delete(API_CACHE), caches.delete(PERSONAL_SHELL_CACHE)]));
    return;
  }

  if (type === 'REPLAY_QUEUE_NOW') {
    event.waitUntil(replayQueue());
  }

  // FEAT-OFFLINE-MSG: إعادة محاولة عنصر فاشل بعينه (زر "إعادة المحاولة"
  // على فقاعة رسالة فشلت — انظر lib/offlineMessagesQueue.ts). يعيد الحالة
  // إلى pending فقط لو نجحت المحاولة فورًا فشلت مجددًا بـ 4xx (replayOne
  // يحدّثها هو نفسه)؛ لو لا يزال أوفلاين فعليًا تبقى الحالة كما أعادها
  // المستخدم ضمنيًا (still-offline لا يغيّر status هنا عمدًا — ستُلتقط
  // بأول replayQueue تلقائي لاحقًا بما أنها لم تعد 'failed').
  if (type === 'RETRY_QUEUE_ITEM' && event.data.id != null) {
    event.waitUntil(
      (async () => {
        const entry = await getQueuedEntry(event.data.id);
        if (!entry) return;
        if (entry.status === 'failed') {
          await markQueuedEntry(entry.id, { status: 'pending' });
        }
        await replayOne({ ...entry, status: 'pending' });
        await notifyClients({ type: 'QUEUE_REPLAYED' });
      })(),
    );
  }

  // FEAT-OFFLINE-MSG: تجاهل نهائي لعنصر فاشل بعينه (زر "حذف" على فقاعة
  // رسالة فشلت) — يُسقطه من الطابور دون أي محاولة إرسال أخرى.
  if (type === 'DISCARD_QUEUE_ITEM' && event.data.id != null) {
    event.waitUntil(
      (async () => {
        await deleteQueuedEntry(event.data.id);
        await notifyClients({ type: 'QUEUE_ITEM_DISCARDED', id: event.data.id });
      })(),
    );
  }
});

self.addEventListener('sync', (event) => {
  if (event.tag === SYNC_TAG) {
    event.waitUntil(replayQueue());
  }
});

// ── Push Notifications ──────────────────────────────────────────
// الحمولة المتوقَّعة من backend/.../pushService.ts: { title, body, url?, tag? }

self.addEventListener('push', (event) => {
  let data = {};
  try {
    data = event.data ? event.data.json() : {};
  } catch {
    data = {};
  }

  const title = data.title || 'سوق غزة';
  const options = {
    body: data.body || '',
    tag: data.tag,
    renotify: Boolean(data.tag),
    data: { url: data.url || '/' },
    icon: '/icon-192',
    badge: '/icon-192',
  };

  event.waitUntil(self.registration.showNotification(title, options));
});

self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const url = (event.notification.data && event.notification.data.url) || '/';

  event.waitUntil(
    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clientsList) => {
      for (const client of clientsList) {
        if (client.url.includes(url) && 'focus' in client) return client.focus();
      }
      if (self.clients.openWindow) return self.clients.openWindow(url);
      return undefined;
    }),
  );
});

// ── Fetch ────────────────────────────────────────────────────────

self.addEventListener('fetch', (event) => {
  const { request } = event;
  const url = new URL(request.url);

  if (request.method !== 'GET') {
    if (isApiRequest(url) && !isNeverCache(url)) {
      event.respondWith(handleMutation(request));
    }
    return;
  }

  if (isNeverCache(url)) {
    return; // شبكة فقط — لا اعتراض، السلوك الافتراضي للمتصفح.
  }

  if (isImageRequest(request, url)) {
    event.respondWith(cacheFirstImage(event, request, url));
    return;
  }

  if (isApiRequest(url)) {
    event.respondWith(networkFirstApi(event, request, url));
    return;
  }

  if (request.mode === 'navigate' || isRscShellRequest(request)) {
    event.respondWith(handlePageRequest(event, request, url));
    return;
  }

  // أصول ثابتة أخرى (JS/CSS chunks إلخ) — نفس App Shell strategy.
  event.respondWith(staleWhileRevalidate(event, request, request));
});

/**
 * ينسخ ملفات تشغيل tesseract من node_modules إلى public/
 * حتى يعمل OCR أوفلاين (بدون CDN).
 */
import { copyFileSync, mkdirSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const pubTess = join(root, 'public', 'tesseract');
const pubData = join(root, 'public', 'tessdata');

mkdirSync(pubTess, { recursive: true });
mkdirSync(pubData, { recursive: true });

function tryCopy(src, dest, label) {
  if (!existsSync(src)) {
    console.warn(`[tessdata:sync] تخطي ${label}: غير موجود (${src})`);
    return false;
  }
  copyFileSync(src, dest);
  console.log(`[tessdata:sync] ✓ ${label}`);
  return true;
}

const nm = join(root, 'node_modules');
const tj = join(nm, 'tesseract.js');
const core = join(nm, 'tesseract.js-core');

tryCopy(join(tj, 'dist', 'worker.min.js'), join(pubTess, 'worker.min.js'), 'worker.min.js');

const coreCandidates = [
  'tesseract-core-simd-lstm.wasm.js',
  'tesseract-core-simd.wasm.js',
  'tesseract-core.wasm.js',
];
let coreJs = null;
for (const name of coreCandidates) {
  const p = join(core, name);
  if (existsSync(p)) {
    coreJs = name;
    tryCopy(p, join(pubTess, 'tesseract-core-simd-lstm.wasm.js'), name);
    const wasmName = name.replace(/\.js$/, '.wasm');
    tryCopy(join(core, wasmName), join(pubTess, wasmName), wasmName);
    break;
  }
}
if (!coreJs) {
  console.warn('[tessdata:sync] لم يُعثر على tesseract.js-core — أبقِ الملفات الحالية في public/tesseract');
}

for (const lang of ['eng', 'ara']) {
  const f = join(pubData, `${lang}.traineddata.gz`);
  if (existsSync(f)) console.log(`[tessdata:sync] ✓ ${lang}.traineddata.gz موجود`);
  else
    console.warn(
      `[tessdata:sync] ناقص: public/tessdata/${lang}.traineddata.gz — حمّله للأوفلاين`,
    );
}

console.log('[tessdata:sync] انتهى');

/**
 * Seller profile types.
 * Mirrors backend's SellerProfile / SellerRating Prisma models
 * (see backend prisma/schema.prisma and seller-profile-design.md).
 *
 * Seller is a state (owning a SellerProfile row), not a Role — there is
 * no `isSeller` boolean or role value here. A user is a seller if and
 * only if a SellerProfile with their userId exists.
 */
import type { AdListItem } from './ad.types';

export type SellerVerificationStatus = 'UNVERIFIED' | 'PENDING' | 'VERIFIED' | 'REJECTED';

export interface SellerProfile {
  id: string;
  userId: string;
  displayName: string;
  bio: string | null;
  avatarUrl: string | null;
  verified: boolean;
  verificationStatus: SellerVerificationStatus;
  verifiedAt: string | null;
  /** 0-1000 — computed server-side only, never client-writable. */
  trustScore: number;
  /**
   * Prisma Decimal(3,2) serialises to string in JSON — same pattern as
   * Ad.price in ad.types.ts. Parse with parseFloat() before display.
   */
  averageRating: string;
  totalRatings: number;
  totalAds: number;
  activeAds: number;
  totalSales: number;
  /** Prisma Decimal(5,2), percentage — string in JSON, or null if unset. */
  responseRate: string | null;
  responseTimeMinutes: number | null;
  paymentMethods?: import("@/types/store.types").StorePaymentMethodDto[] | null;
  joinedSellingAt: string;
  createdAt: string;
  updatedAt: string;
}

/**
 * GET /sellers/:id — public seller page, includes their active ads.
 * `user.city` is the seller's location — lives on User, not
 * SellerProfile (a seller has exactly one, unlike StoreDetails/
 * ServiceProviderDetails which each carry their own).
 */
export type SellerProfileWithAds = SellerProfile & {
  ads: AdListItem[];
  user: { city: string | null };
};

/** Payload for POST /sellers/me/profile */
export interface CreateSellerProfilePayload {
  displayName?: string;
  bio?: string;
  avatarUrl?: string;
  agreedToSellerTerms: true;
}

/** Payload for PATCH /sellers/me/profile */
export interface UpdateSellerProfilePayload {
  displayName?: string;
  bio?: string | null;
  avatarUrl?: string | null;
  paymentMethods?: import('@/types/store.types').StorePaymentMethodDto[] | null;
}

/** GET /sellers/me/attention — dashboard task counters */
export interface SellerAttention {
  adsMissingImages: number;
  productsOutOfStock: number;
  productsMissingImages: number;
  pendingServiceRequests: number;
  hasStore: boolean;
  isProvider: boolean;
}

/** Payload for POST /sellers/:id/ratings */
export interface CreateSellerRatingPayload {
  adId?: string;
  score: 1 | 2 | 3 | 4 | 5;
  comment?: string;
}

/**
 * GET /sellers/:id/ratings row. Same "always included" convention as
 * StoreReview.rater/ServiceReview.rater — every row comes from
 * sellers.repository.ts's findManyRatingsBySellerProfileId, which
 * always joins the rater. `ad` is this type's one difference from
 * StoreReview/ServiceReview: a SellerRating can optionally be scoped
 * to one specific ad transaction (CreateSellerRatingPayload.adId is
 * optional), so it's null whenever the rating wasn't tied to a
 * particular ad.
 */
export interface SellerRating {
  id: string;
  score: number;
  comment: string | null;
  sellerProfileId: string;
  raterId: string;
  adId: string | null;
  createdAt: string;
  rater: {
    id: string;
    name: string;
    avatarUrl: string | null;
  };
  ad: {
    id: string;
    title: string;
  } | null;
}

/**
 * User types.
 * Mirrors backend Prisma User model and SafeUser select.
 */

// FIX BUG-XX: this used to redeclare UserRole as 'USER' | 'ADMIN',
// stale relative to auth.types.ts's correct 4-value union ('USER' |
// 'MODERATOR' | 'ADMIN' | 'SUPER_ADMIN', kept in sync with the
// backend Prisma Role enum since Gap #20). No current code imported
// UserRole from here, but `User.role: UserRole` below inherited the
// narrow type, and any exhaustive switch added later on a `User`
// object's `.role` would silently miss MODERATOR/SUPER_ADMIN. Re-
// exporting from auth.types.ts makes it a single source of truth
// instead of two definitions that can drift again.
import type { UserRole } from './auth.types';
import type { ServiceBusinessType, ServiceAvailability } from './service.types';
import type { StorePlan } from './store.types';

/** Full user — returned by GET /users/me */
/** FIX FEAT-02: matches NotificationSettingsForm.tsx's SETTINGS keys
 * and the backend's updateNotificationPreferencesSchema exactly. */
export interface NotificationPreferences {
  newMessage:   boolean;
  adViews:      boolean;
  favAdUpdated: boolean;
  promotions:   boolean;
  /** PROMO-1: store owner's own Promotion lifecycle alerts. */
  myPromotions: boolean;
  /** Matches for saved searches (ads/products/services). */
  savedSearch: boolean;
  /** Followed-store product / promotion / restock alerts. */
  storeUpdates: boolean;
  /** Service broadcast quote submitted / accepted. */
  serviceQuotes: boolean;
}

export interface User {
  id:        string;
  name:      string;
  email:     string;
  phone:     string | null;
  city:      string | null;
  bio:       string | null;
  avatarUrl: string | null;
  role:      UserRole;
  isActive:  boolean;
  notificationPreferences: NotificationPreferences;
  createdAt: string;
  updatedAt: string;
}

/**
 * UNIFIED-PROFILE: the seller/store/service-provider "roles" attached to
 * a public profile, mirroring backend users.repository.ts's
 * publicUserSelect exactly (field-for-field — nothing here that
 * endpoint doesn't already return). All three are optional/nullable on
 * the person: a plain user has sellerProfile: null; a seller with
 * neither a store nor a service business has both children null.
 */
export interface PublicProfileStore {
  id:            string;
  name:          string;
  description:   string;
  logoUrl:       string | null;
  coverImageUrl: string | null;
  city:          string;
  plan:          StorePlan;
  phone?:        string;
  // UNIFY-PAYMENTS-STORES: no paymentMethods here anymore — use the
  // parent PublicSellerProfile.paymentMethods instead (single source
  // of truth, same as PublicProfileServiceProvider).
  _count: { followers: number; products: number };
}

export interface PublicProfileServiceProvider {
  id:                     string;
  businessName:           string;
  businessType:           ServiceBusinessType;
  logoUrl:                string | null;
  description:            string;
  serviceAreaCities:      string[];
  availabilityStatus:     ServiceAvailability;
  completedRequestsCount: number;
  /** Public contact — call / WhatsApp on the profile services tab. */
  contactPhone:           string;
  // UNIFY-PAYMENTS: no paymentMethods here anymore — use the parent
  // PublicSellerProfile.paymentMethods instead (single source of truth).
}

export interface PublicSellerProfile {
  id:              string;
  displayName:     string;
  bio:             string | null;
  avatarUrl:       string | null;
  verified:        boolean;
  trustScore:      number;
  averageRating:   string;
  totalRatings:    number;
  activeAds:       number;
  totalSales:      number;
  /** Prisma Decimal(5,2), percentage — string in JSON, or null if the
   *  seller-response-metrics job hasn't measured them yet (no
   *  conversations in its lookback window). */
  responseRate:        string | null;
  responseTimeMinutes: number | null;
  joinedSellingAt: string;
  paymentMethods?: import('@/types/store.types').StorePaymentMethodDto[] | null;
  _count: { serviceReviews: number };
  storeDetails:            PublicProfileStore | null;
  serviceProviderDetails:  PublicProfileServiceProvider | null;
}

/** Public profile — returned by GET /users/:id (no email/phone) */
export type PublicUser = Pick<User, 'id' | 'name' | 'city' | 'bio' | 'avatarUrl' | 'createdAt'> & {
  _count: { ads: number };
  sellerProfile: PublicSellerProfile | null;
};

/**
 * Payload for PATCH /users/me.
 *
